function EN_LESSON_NAMES(grade, unitIndex) {
  const u = `Unit ${unitIndex}`;
  if (grade === "g5") {
    return [
      `${u} \xB7 A Let's try & Let's talk`,
      `${u} \xB7 A Let's learn`,
      `${u} \xB7 Let's spell`,
      `${u} \xB7 B Let's try & Let's talk`,
      `${u} \xB7 B Let's learn`,
      `${u} \xB7 Story time`
    ];
  }
  if (grade === "g6") {
    return [
      `${u} \xB7 A Let's try & Let's talk`,
      `${u} \xB7 A Let's learn`,
      `${u} \xB7 B Let's try & Let's talk`,
      `${u} \xB7 B Let's learn`,
      `${u} \xB7 Read and write`,
      `${u} \xB7 Story time`
    ];
  }
  return [
    `${u} \xB7 A Let's talk`,
    `${u} \xB7 A Let's learn`,
    `${u} \xB7 Letters and sounds`,
    `${u} \xB7 B Let's talk`,
    `${u} \xB7 B Let's learn`,
    `${u} \xB7 Start to read & Story time`
  ];
}
