        check: { q: "\u8001\u7956\u6BCD\u8BF4\u5C0F\u516C\u4E3B\u6EE1\u5341\u4E94\u5C81\u5C31\u53EF\u4EE5\u505A\u4EC0\u4E48\uFF1F", options: ["\u6D6E\u5230\u6D77\u9762\u4E0A\u53BB", "\u53D8\u6210\u5C0F\u9E1F", "\u5F53\u4E0A\u5973\u738B"], answer: 0 }
