        figure: { type: "scene", emojis: ["\u{1F33E}", "\u{1F468}\u200D\u{1F373}", "\u{1F392}", "\u{1F3D4}\uFE0F"], title: "\u8349\u5730\u884C\u524D\u63A5\u91CD\u6258" },
