        check: { q: "\u8BFE\u6587\u544A\u8BC9\u6211\u4EEC\u6700\u91CD\u8981\u7684\u9053\u7406\u662F\u4EC0\u4E48\uFF1F", options: ["\u8981\u7CBE\u5FC3\u4FDD\u62A4\u5730\u7403\uFF0C\u4FDD\u62A4\u751F\u6001\u73AF\u5883", "\u591A\u9020\u98DE\u8239\u53BB\u592A\u7A7A", "\u8282\u7EA6\u7528\u7535\u5C31\u884C"], answer: 0 }
