        check: { q: "\u6253\u5F00\u8868\u76D6\u540E\uFF0C\u201C\u6211\u201D\u770B\u89C1\u4E86\u4EC0\u4E48\uFF1F", options: ["\u5C0F\u9F7F\u8F6E\u548C\u5F39\u7C27", "\u4E00\u53EA\u771F\u7684\u5C0F\u874E\u5B50", "\u4E00\u53EA\u5C0F\u8682\u8681"], answer: 0 }
