        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F534}", "\u{1F4DD}", "\u{1F58D}\uFE0F", "\u{1F497}"], title: "\u4E24\u4E2A\u7EA2\u5708\u5F15\u4E0A\u8DEF", text: "\u4F5C\u6587\u4E0A\u7684\u7EA2\u53CC\u5708\uFF0C\u70B9\u4EAE\u5199\u4F5C\u8DEF" },
        check: { q: "\u201C\u7EA2\u53CC\u5708\u201D\u5BF9\u4F5C\u8005\u6709\u4EC0\u4E48\u5F71\u54CD\uFF1F", options: ["\u628A\u5979\u5F15\u4E0A\u4E86\u5199\u4F5C\u7684\u9053\u8DEF", "\u8BA9\u5979\u5F97\u4E86\u5956\u72B6", "\u8BA9\u5979\u5F53\u4E86\u73ED\u957F"], answer: 0 }
