        check: { q: "\u62FF\u5230\u65B0\u4E66\uFF0C\u7B2C\u4E00\u6B65\u5148\u505A\u4EC0\u4E48\uFF1F", options: ["\u770B\u5C01\u9762\u4E0A\u7684\u4E66\u540D\u548C\u4F5C\u8005", "\u770B\u6700\u540E\u4E00\u9875", "\u53EA\u770B\u4E2D\u95F4\u7684\u63D2\u56FE"], answer: 0 }
