        check: { q: "\u6BCF\u5929\u8BFB\u4E66\u591A\u957F\u65F6\u95F4\u6BD4\u8F83\u5408\u9002\uFF1F", options: ["\u4E8C\u5341\u5206\u949F\u5DE6\u53F3", "\u4E00\u5C0F\u65F6\u4E0D\u4F11\u606F", "\u770B\u5FC3\u60C5\uFF0C\u4E00\u5929\u4E5F\u4E0D\u8BFB"], answer: 0 }
