        example: "\u4E00\u53EA\u6D77\u9E25\uFF0C\u4E00\u7247\u6C99\u6EE9\uFF0C\u6D77\u98CE\u8F7B\u8F7B\u5439\u3002",
        figure: { type: "scene", bg: "water", emojis: ["\u{1F30A}", "\u{1F54A}\uFE0F", "\u26F5"], title: "\u6D77\u8FB9\u7684\u573A\u666F\u6B4C", text: "\u6D77\u9E25\u6C99\u6EE9\u519B\u8230\u5E06\u8239\uFF0C\u6D77\u8FB9\u98CE\u5149\u7F8E\u3002" },
        check: { q: "\u6D77\u9E25\u5E94\u8BE5\u7528\u54EA\u4E2A\u91CF\u8BCD\uFF1F", options: ["\u4E00\u53EA", "\u4E00\u7247", "\u4E00\u8258"], answer: 0 }
