        text: '\u91CF\u8BCD\u8981\u548C\u4E8B\u7269\u642D\u914D\u597D\uFF1A\u519B\u8230\u7528"\u8258"\uFF0C\u5E06\u8239\u7528"\u6761"\uFF0C\u82B1\u56ED\u7528"\u5EA7"\uFF0C\u5782\u67F3\u7528"\u884C"\u3002\u8BFB\u7684\u65F6\u5019\u8FB9\u8BFB\u8FB9\u5728\u8111\u5B50\u91CC\u753B\u753B\u9762\uFF0C\u8FD9\u9996\u300A\u573A\u666F\u6B4C\u300B\u5C31\u7262\u7262\u8BB0\u4F4F\u5566\u3002',
        example: "\u4E00\u4E32\u8461\u8404\u3001\u4E00\u5F20\u684C\u5B50\u3001\u4E00\u6247\u7A97\u6237\u2014\u2014\u4F60\u8FD8\u4F1A\u8BF4\u5417\uFF1F",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F9E9}", "\u270F\uFE0F", "\u{1F3B5}"], title: "\u642D\u914D\u91CF\u8BCD\u5C0F\u6E38\u620F", text: "\u91CF\u8BCD\u50CF\u5C0F\u5E3D\u5B50\uFF0C\u6234\u5BF9\u4E86\u624D\u5408\u9002\u3002" },
        check: { q: "\u4E0B\u9762\u7684\u91CF\u8BCD\u642D\u914D\uFF0C\u54EA\u4E2A\u662F\u5BF9\u7684\uFF1F", options: ["\u4E00\u5EA7\u82B1\u56ED", "\u4E00\u6761\u82B1\u56ED", "\u4E00\u7247\u82B1\u56ED"], answer: 0 }
