    quiz: { q: "\u4E0B\u9762\u54EA\u4E2A\u91CF\u8BCD\u642D\u914D\u662F\u6B63\u786E\u7684\uFF1F", options: ["\u4E00\u6761\u5782\u67F3", "\u4E00\u884C\u5782\u67F3", "\u4E00\u5EA7\u5782\u67F3"], answer: 1 }
