        figure: { type: "scene", bg: "forest", emojis: ["\u{1F341}", "\u{1F332}", "\u{1F342}"], title: "\u7EA2\u53F6\u4E0E\u5E38\u9752\u6811", text: "\u67AB\u53F6\u79CB\u5929\u7EA2\uFF0C\u677E\u67CF\u56DB\u5B63\u7EFF\u3002" },
