        check: { q: '"\u4E94\u4E5D\u516D\u4E5D"\u7684\u65F6\u5019\uFF0C\u4EBA\u4EEC\u505A\u4EC0\u4E48\uFF1F', options: ["\u6CBF\u6CB3\u770B\u67F3", "\u7F29\u624B\u4E0D\u51FA\u95E8", "\u5728\u51B0\u4E0A\u8D70"], answer: 0 }
