        check: { q: "\u5C0F\u670B\u53CB\u628A\u4EC0\u4E48\u6302\u5728\u5F69\u8679\u6865\u4E0A\u8361\u6765\u8361\u53BB\uFF1F", options: ["\u79CB\u5343", "\u6C34\u58F6", "\u955C\u5B50"], answer: 0 }
