        check: { q: "\u7956\u9016\u542C\u5230\u4EC0\u4E48\u58F0\u97F3\u5C31\u8D77\u5E8A\u7EC3\u6B66\uFF1F", options: ["\u9E21\u53EB", "\u949F\u58F0", "\u9E1F\u53EB"], answer: 0 }
