        check: { q: '"\u7591\u662F\u94F6\u6CB3\u843D\u4E5D\u5929"\u628A\u7011\u5E03\u6BD4\u4F5C\u4EC0\u4E48\uFF1F', options: ["\u94F6\u6CB3", "\u767D\u4E91", "\u5F69\u8679"], answer: 0 }
