        check: { q: "\u4E5D\u5341\u6708\u4EFD\uFF0C\u8461\u8404\u6C9F\u4EC0\u4E48\u6C34\u679C\u6210\u719F\u4E86\uFF1F", options: ["\u8461\u8404", "\u674F\u5B50", "\u6C99\u679C"], answer: 0 }
