    quiz: { q: "\u4E0B\u9762\u7684\u8BCD\uFF0C\u54EA\u4E2A\u662F\u5F62\u5BB9\u989C\u8272\u7684\uFF1F", options: ["\u7FE0\u7EFF", "\u98DE\u5FEB", "\u54CD\u4EAE"], answer: 0 }
