        figure: { type: "scene", bg: "field", emojis: ["\u{1F438}", "\u{1F305}", "\u{1F30D}"], title: "\u8DF3\u51FA\u4E95\u53E3\u770B\u4E16\u754C", text: "\u8DF3\u51FA\u4E95\u53E3\uFF0C\u770B\u89C1\u5927\u5927\u7684\u4E16\u754C\u3002" },
