    rhyme: "\u5C0F\u737E\u505A\u51F3\u771F\u8BA4\u771F\uFF0C\u523A\u732C\u5938\u4ED6\u4E00\u4E2A\u6BD4\u4E00\u4E2A\u597D\uFF1B\n\u79F0\u8D5E\u8BA9\u4EBA\u6709\u81EA\u4FE1\uFF0C\u6905\u5B50\u505A\u5F97\u7262\u53C8\u7262\uFF1B\n\u771F\u8BDA\u79F0\u8D5E\u522B\u4EBA\uFF0C\u5FEB\u4E50\u81EA\u5DF1\u4E5F\u6765\u5230\u3002",
