        figure: { type: "scene", bg: "water", emojis: ["\u26F2", "\u{1F91D}", "\u{1F4A7}"], title: "\u6CC9\u6C34\u597D\u670B\u53CB", text: "\u6CC9\u6C34\u6454\u8DDF\u5934\u4E5F\u4E0D\u6015\uFF0C\u52C7\u6562\u5411\u524D\u3002" },
        check: { q: "\u6CC9\u6C34\u4ECE\u5C71\u4E0A\u8DF3\u4E0B\u6765\u6454\u4E86\u5F88\u591A\u8DDF\u5934\uFF0C\u5B83\u600E\u4E48\u6837\uFF1F", options: ["\u5531\u7740\u6B4C\u52C7\u6562\u5411\u524D", "\u54ED\u4E2A\u4E0D\u505C", "\u505C\u4E0B\u6765\u4E0D\u8D70\u4E86"], answer: 0 }
