        text: "\u56E0\u4E3A\u8D1D\u58F3\u66FE\u7ECF\u5F53\u8FC7\u94B1\u5E01\uFF0C\u6240\u4EE5\u5E26\u201C\u8D1D\u201D\u7684\u5B57\u5927\u591A\u548C\u94B1\u8D22\u6709\u5173\uFF1A\u8D5A\u662F\u6323\u94B1\uFF0C\u8D54\u662F\u4E8F\u94B1\uFF0C\u8D2D\u662F\u4E70\u4E1C\u897F\uFF0C\u8D2B\u662F\u6CA1\u6709\u94B1\uFF0C\u8D27\u662F\u8D27\u7269\u3002\u8BA4\u8BC6\u4E00\u4E2A\u201C\u8D1D\u201D\uFF0C\u5C31\u80FD\u731C\u51FA\u4E00\u4E32\u5B57\u7684\u610F\u601D\u3002",
        example: "\u8D5A\u3001\u8D54\u3001\u8D2D\u3001\u8D2B\u2026\u2026\u8FD9\u4E9B\u5B57\u91CC\u90FD\u85CF\u7740\u201C\u8D1D\u201D\u3002",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F41A}", "\u{1F48E}", "\u{1F9E0}"], title: "\u8D1D\u5B57\u5BB6\u65CF", text: "\u5E26\u8D1D\u7684\u5B57\uFF0C\u5927\u591A\u548C\u94B1\u8D22\u6709\u5173\u3002" },
        check: { q: "\u4E0B\u9762\u54EA\u4E2A\u5B57\u5927\u591A\u548C\u94B1\u8D22\u6709\u5173\uFF1F", options: ["\u8D5A", "\u6E56", "\u8DD1"], answer: 0 }
