    quiz: { q: "\u4E3A\u4EC0\u4E48\u5E26\u201C\u8D1D\u201D\u7684\u5B57\u5927\u591A\u548C\u94B1\u8D22\u6709\u5173\uFF1F", options: ["\u56E0\u4E3A\u8D1D\u58F3\u66FE\u5F53\u8FC7\u94B1\u5E01", "\u8D1D\u58F3\u662F\u7EA2\u8272\u7684", "\u8D1D\u58F3\u7279\u522B\u8F7B"], answer: 0 }
