    quiz: { q: "\u300A\u82B1\u7684\u5B66\u6821\u300B\u628A\u82B1\u6735\u5F53\u4F5C\u4EC0\u4E48\u6765\u5199\uFF1F", options: ["\u4E0A\u5B66\u3001\u653E\u5047\u7684\u5B69\u5B50", "\u4F1A\u98DE\u7684\u5C0F\u9E1F", "\u5B89\u9759\u7684\u77F3\u5934"], answer: 0 }
