        figure: { type: "scene", bg: "city", emojis: ["\u{1F342}", "\u{1F590}\uFE0F", "\u{1F6E4}\uFE0F"], title: "\u91D1\u8272\u7684\u5C0F\u5DF4\u638C", text: "\u68A7\u6850\u843D\u53F6\u7C98\u5728\u6C34\u6CE5\u9053\u4E0A\uFF0C\u50CF\u91D1\u8272\u7684\u5C0F\u5DF4\u638C\u3002" },
        check: { q: "\u91D1\u9EC4\u7684\u68A7\u6850\u53F6\u50CF\u4EC0\u4E48\uFF1F", options: ["\u91D1\u8272\u7684\u5C0F\u5DF4\u638C", "\u5F69\u8272\u7684\u5C0F\u9E1F", "\u4EAE\u6676\u6676\u7684\u6C34\u6D3C"], answer: 0 }
