        check: { q: "\u4F5C\u8005\u628A\u94FA\u6EE1\u843D\u53F6\u7684\u6C34\u6CE5\u9053\u6BD4\u4F5C\u4EC0\u4E48\uFF1F", options: ["\u5F69\u8272\u7684\u5730\u6BEF", "\u4E00\u6761\u5C0F\u6CB3", "\u91D1\u8272\u7684\u6D77\u6D0B"], answer: 0 }
