        check: { q: "\u8349\u5730\u4E2D\u5348\u4E3A\u4EC0\u4E48\u53D8\u6210\u91D1\u8272\uFF1F", options: ["\u84B2\u516C\u82F1\u7684\u82B1\u74E3\u5F20\u5F00\u4E86", "\u592A\u9633\u628A\u5B83\u6652\u9EC4\u4E86", "\u5C0F\u8349\u6362\u4E86\u65B0\u8863\u88F3"], answer: 0 }
