        figure: { type: "scene", bg: "mountain", emojis: ["\u{1F3D4}\uFE0F", "\u{1F304}", "\u{1FAA8}"], title: "\u7A7A\u5C71\u95FB\u4EBA\u8BED", text: "\u7A7A\u5C71\u4E0D\u89C1\u4EBA\uFF0C\u4F46\u95FB\u4EBA\u8BED\u54CD\uFF0C\u8FD4\u666F\u5165\u6DF1\u6797\u3002" },
        check: { q: "\u300A\u9E7F\u67F4\u300B\u662F\u600E\u6837\u5199\u51FA\u5C71\u6797\u7684\u5E7D\u9759\u7684\uFF1F", options: ['\u7528"\u4EBA\u8BED\u54CD"\u548C"\u8FD4\u666F"\u4EE5\u52A8\u886C\u9759', "\u8BA9\u52A8\u7269\u5927\u58F0\u53EB", "\u628A\u5C71\u753B\u6210\u9ED1\u8272"], answer: 0 }
