    quiz: { q: "\u300A\u53F8\u9A6C\u5149\u300B\u8FD9\u7BC7\u8BFE\u6587\u662F\u4EC0\u4E48\u4F53\u88C1\uFF1F", options: ["\u6587\u8A00\u6587", "\u73B0\u4EE3\u8BD7", "\u7AE5\u8BDD"], answer: 0 }
