        check: { q: "\u767D\u6C42\u6069\u5927\u592B\u5728\u54EA\u91CC\u7ED9\u4F24\u5458\u505A\u624B\u672F\uFF1F", options: ["\u79BB\u706B\u7EBF\u4E0D\u8FDC\u7684\u5C0F\u5E99\u91CC", "\u540E\u65B9\u7684\u5927\u533B\u9662\u91CC", "\u81EA\u5DF1\u7684\u5BB6\u91CC"], answer: 0 }
