    quiz: { q: "\u4ECE\u767D\u6C42\u6069\u8EAB\u4E0A\uFF0C\u6211\u4EEC\u5B66\u5230\u4E86\u4EC0\u4E48\u7CBE\u795E\uFF1F", options: ["\u5BF9\u5DE5\u4F5C\u6781\u7AEF\u8D1F\u8D23\uFF0C\u575A\u5B88\u5C97\u4F4D", "\u9047\u5230\u5371\u9669\u5C31\u5148\u8DD1", "\u53EA\u5173\u5FC3\u81EA\u5DF1\u7684\u5B89\u5168"], answer: 0 }
