    quiz: { q: "\u4E0B\u9762\u54EA\u4EF6\u4E8B\u4E0D\u662F\u957F\u80E1\u5B50\u5E2E\u5FD9\u505A\u7684\uFF1F", options: ["\u5E2E\u5C0F\u72D7\u627E\u9AA8\u5934", "\u7ED9\u7537\u5B69\u653E\u98CE\u7B5D", "\u7ED9\u9E1F\u592A\u592A\u667E\u5C3F\u5E03"], answer: 0 }
