        check: { q: "\u82F1\u82F1\u53D8\u6210\u7684\u6811\u4E0A\u957F\u6EE1\u4E86\u4EC0\u4E48\uFF1F", options: ["\u5404\u79CD\u5F62\u72B6\u7684\u9E1F\u7A9D", "\u5927\u82F9\u679C", "\u7EA2\u6A31\u6843"], answer: 0 }
