        check: { q: "\u5988\u5988\u7684\u5927\u80CC\u5305\u91CC\u88C5\u7684\u662F\u4EC0\u4E48\uFF1F", options: ["\u597D\u5403\u7684\u98DF\u7269", "\u4E00\u645E\u4F5C\u4E1A\u672C", "\u5C0F\u52A8\u7269\u4EEC\u7684\u8863\u670D"], answer: 0 }
