    rhyme: "\u590D\u8FF0\u6545\u4E8B\u6709\u5999\u62DB\uFF0C\u8868\u683C\u56FE\u793A\u6765\u68B3\u7406\uFF1B\n\u564C\u7684\u4E00\u4E0B\u6251\u901A\u4E00\u58F0\uFF0C\u62DF\u58F0\u8BCD\u513F\u771F\u751F\u52A8\uFF1B\n\u5175\u6765\u5C06\u6321\u6C34\u6765\u571F\u63A9\uFF0C\u773C\u89C1\u4E3A\u5B9E\u8033\u542C\u4E3A\u865A\u3002",
