        check: { q: "\u6F6E\u6765\u524D\uFF0C\u94B1\u5858\u6C5F\u9762\u662F\u4EC0\u4E48\u6837\u5B50\uFF1F", options: ["\u5F88\u5E73\u9759\uFF0C\u7B3C\u7F69\u7740\u8584\u96FE", "\u5DE8\u6D6A\u6ED4\u5929", "\u7ED3\u4E86\u4E00\u5C42\u51B0"], answer: 0 }
