        check: { q: "\u4ECE\u524D\u5728\u5BB6\u4E61\uFF0C\u4F5C\u8005\u5728\u54EA\u513F\u770B\u661F\u661F\uFF1F", options: ["\u5EAD\u9662\u7684\u591C\u7A7A\u4E0B", "\u5927\u6D77\u7684\u7532\u677F\u4E0A", "\u6559\u5BA4\u91CC"], answer: 0 }
