        check: { q: "\u8BA9\u8001\u9EBB\u96C0\u98DE\u4E0B\u6765\u6551\u5E7C\u513F\u7684\u201C\u4E00\u79CD\u5F3A\u5927\u7684\u529B\u91CF\u201D\u662F\u4EC0\u4E48\uFF1F", options: ["\u5BF9\u5C0F\u9EBB\u96C0\u7684\u7231", "\u730E\u72D7\u7684\u543C\u53EB", "\u98CE\u5439\u7684\u529B\u91CF"], answer: 0 }
