var CHG5E_B_P2 = {
  /* ------------------------------ 第五单元 ------------------------------ */
  "chinese-g5-b-5-1": {
    example: "\u8FD9\u4E00\u8BFE\u5F88\u7279\u522B\uFF0C\u5B83\u7531\u4E09\u7BC7\u5199\u4EBA\u7684\u77ED\u6587\u7EC4\u6210\uFF1A\u300A\u6454\u8DE4\u300B\u91CC\u7684\u5C0F\u560E\u5B50\u3001\u300A\u4ED6\u50CF\u4E00\u68F5\u633A\u8131\u7684\u6811\u300B\u91CC\u7684\u7965\u5B50\u3001\u300A\u4E24\u830E\u706F\u8349\u300B\u91CC\u7684\u4E25\u76D1\u751F\u3002\u540C\u6837\u662F\u5199\u4EBA\uFF0C\u7528\u7684\u65B9\u6CD5\u5374\u4E0D\u4E00\u6837\uFF0C\u6211\u4EEC\u4E00\u8D77\u53BB\u53D1\u73B0\u3002",
    steps: [
      {
        title: "\u300A\u6454\u8DE4\u300B\uFF1A\u52A8\u4F5C\u91CC\u6709\u673A\u7075",
        text: "\u5C0F\u560E\u5B50\u8DDF\u4EBA\u6454\u8DE4\uFF0C\u4E00\u5411\u4ED7\u7740\u624B\u75BE\u773C\u5FEB\uFF0C\u4ECE\u4E0D\u5355\u51ED\u529B\u6C14\u3002\u8FD9\u56DE\u8DDF\u5C0F\u80D6\u58A9\u513F\u6BD4\uFF0C\u4ED6\u6BD4\u4EBA\u5BB6\u7626\u3001\u529B\u6C14\u4E5F\u5C0F\uFF0C\u53EF\u4ED6\u673A\u7075\uFF1A\u4E00\u4EA4\u624B\uFF0C\u5C31\u56F4\u7740\u5C0F\u80D6\u58A9\u513F\u7334\u513F\u4F3C\u7684\u8E66\u6765\u8E66\u53BB\uFF0C\u603B\u60F3\u4F7F\u5DE7\u62DB\u3001\u4E0B\u51B7\u7ECA\u5B50\uFF0C\u4EFF\u4F5B\u5360\u4E86\u4E0A\u98CE\u3002\u53EF\u5C0F\u80D6\u58A9\u513F\u4E0D\u614C\u4E0D\u5FD9\uFF0C\u53EA\u7B49\u5C0F\u560E\u5B50\u8F6C\u5230\u8DDF\u524D\uFF0C\u5C31\u52BF\u5F80\u65C1\u4FA7\u91CC\u4E00\u63A8\u2014\u2014\u5495\u549A\u4E00\u58F0\uFF0C\u5C0F\u560E\u5B50\u6454\u4E86\u4E2A\u4EF0\u9762\u671D\u5929\u3002\u8BFE\u6587\u9760\u4E00\u8FDE\u4E32\u52A8\u4F5C\uFF0C\u628A\u673A\u7075\u53C8\u6709\u70B9\u800D\u5C0F\u806A\u660E\u7684\u560E\u5B50\u5199\u6D3B\u4E86\u3002",
        example: "\u5C0F\u560E\u5B50\u56F4\u7740\u5BF9\u624B\u8E66\u6765\u8E66\u53BB\uFF0C\u60F3\u4F7F\u5DE7\u62DB\u4E0B\u51B7\u7ECA\u5B50\uFF0C\u5374\u88AB\u8F7B\u8F7B\u4E00\u63A8\uFF0C\u6454\u4E86\u4E2A\u4EF0\u9762\u671D\u5929\u3002",
        figure: { type: "scene", bg: "city", emojis: ["\u{1F466}", "\u{1F93C}", "\u{1F4A8}"], title: "\u9662\u91CC\u7684\u4E00\u573A\u6454\u8DE4", text: "\u9662\u5B50\u91CC\u5C0F\u560E\u5B50\u8E66\u6765\u8E66\u53BB\uFF0C\u603B\u60F3\u4F7F\u5DE7\u62DB\u3002" },
        check: { q: "\u5C0F\u560E\u5B50\u6454\u8DE4\u53D6\u80DC\u9760\u7684\u662F\u4EC0\u4E48\uFF1F", options: ["\u673A\u7075\uFF0C\u4F1A\u4F7F\u5DE7\u62DB\u3001\u4E0B\u51B7\u7ECA\u5B50", "\u4E2A\u5B50\u9AD8\u529B\u6C14\u5927", "\u573A\u5730\u5BF9\u4ED6\u6709\u5229"], answer: 0 }
      },
      {
        title: "\u4ED6\u50CF\u4E00\u68F5\u633A\u8131\u7684\u6811",
        text: "\u8001\u820D\u7237\u7237\u5199\u7965\u5B50\uFF1A\u4E8C\u5341\u6765\u5C81\uFF0C\u8EAB\u91CF\u4E0E\u7B4B\u8089\u90FD\u957F\u5230\u524D\u5934\u53BB\u4E86\uFF0C\u5F88\u5927\u5F88\u9AD8\uFF0C\u8138\u4E0A\u8EAB\u4E0A\u90FD\u5E26\u51FA\u5929\u771F\u6DD8\u6C14\u7684\u6837\u5B50\u3002\u4ED6\u8BA1\u5212\u7740\u6740\u8FDB\u8170\u53BB\uFF0C\u597D\u66F4\u663E\u51FA\u94C1\u6247\u9762\u4F3C\u7684\u80F8\u548C\u76F4\u786C\u7684\u80CC\uFF1B\u53C8\u626D\u5934\u770B\u81EA\u5DF1\u7684\u80A9\uFF0C\u591A\u4E48\u5BBD\u3001\u591A\u4E48\u5A01\u4E25\uFF01\u6740\u597D\u4E86\u8170\uFF0C\u518D\u7A7F\u4E0A\u80A5\u817F\u7684\u767D\u88E4\uFF0C\u88E4\u811A\u7528\u9E21\u80A0\u5B50\u5E26\u513F\u7CFB\u4F4F\uFF0C\u9732\u51FA\u90A3\u53CC\u201C\u51FA\u53F7\u201D\u7684\u5927\u811A\u3002\u8BFB\u7740\u8BFB\u7740\uFF0C\u4E00\u4E2A\u9AD8\u5927\u7ED3\u5B9E\u3001\u5145\u6EE1\u671D\u6C14\u7684\u5C0F\u4F19\u5B50\u5C31\u7AD9\u5728\u6211\u4EEC\u9762\u524D\u4E86\u2014\u2014\u8FD9\u5C31\u662F\u5916\u8C8C\u63CF\u5199\u3002",
        example: "\u94C1\u6247\u9762\u4F3C\u7684\u80F8\u3001\u76F4\u786C\u7684\u80CC\u3001\u5BBD\u5BBD\u7684\u80A9\uFF0C\u7965\u5B50\u50CF\u4E00\u68F5\u633A\u62D4\u58EE\u5B9E\u7684\u5927\u6811\u3002",
        figure: { type: "scene", bg: "city", emojis: ["\u{1F333}", "\u{1F4AA}", "\u{1F456}"], title: "\u633A\u8131\u5065\u58EE\u7684\u8F66\u592B", text: "\u5927\u8857\u4E0A\u5065\u58EE\u7684\u8F66\u592B\uFF0C\u50CF\u4E00\u68F5\u633A\u62D4\u7684\u5927\u6811\u3002" },
        check: { q: "\u201C\u4ED6\u50CF\u4E00\u68F5\u633A\u8131\u7684\u6811\u201D\u4E3B\u8981\u7528\u4E86\u4EC0\u4E48\u63CF\u5199\uFF1F", options: ["\u5916\u8C8C\u63CF\u5199", "\u52A8\u4F5C\u63CF\u5199", "\u5FC3\u7406\u63CF\u5199"], answer: 0 }
      },
      {
        title: "\u300A\u4E24\u830E\u706F\u8349\u300B\uFF1A\u4E00\u6839\u624B\u6307\u89C1\u541D\u556C",
        text: "\u4E25\u76D1\u751F\u5FEB\u65AD\u6C14\u4E86\uFF0C\u5589\u5499\u91CC\u7684\u75F0\u54CD\u5F97\u4E00\u8FDB\u4E00\u51FA\uFF0C\u5374\u603B\u4E0D\u5F97\u65AD\u6C14\uFF0C\u8FD8\u4ECE\u88AB\u5355\u91CC\u4F38\u51FA\u4E24\u4E2A\u6307\u5934\u3002\u5927\u4F84\u5B50\u731C\u662F\u8FD8\u6709\u4E24\u4E2A\u4EB2\u4EBA\u6CA1\u89C1\u9762\uFF0C\u4ED6\u6447\u5934\uFF1B\u4E8C\u4F84\u5B50\u731C\u662F\u8FD8\u6709\u4E24\u7B14\u94F6\u5B50\u6CA1\u5429\u5490\uFF0C\u4ED6\u4E24\u773C\u7741\u5F97\u6EF4\u6E9C\u5706\uFF0C\u5934\u6447\u5F97\u66F4\u72E0\uFF1B\u5976\u5988\u8BF4\u4ED6\u662F\u8BB0\u5FF5\u4E24\u4F4D\u8205\u7237\uFF0C\u4ED6\u95ED\u7740\u773C\u8FD8\u662F\u6447\u5934\u3002\u53EA\u6709\u8D75\u6C0F\u61C2\u4ED6\uFF1A\u662F\u5ACC\u706F\u76CF\u91CC\u70B9\u7740\u4E24\u830E\u706F\u8349\uFF0C\u6015\u8D39\u4E86\u6CB9\uFF01\u6311\u6389\u4E00\u830E\uFF0C\u4ED6\u624D\u70B9\u4E00\u70B9\u5934\uFF0C\u5782\u4E0B\u624B\uFF0C\u767B\u65F6\u6CA1\u4E86\u6C14\u3002\u8BFE\u6587\u6293\u4F4F\u201C\u4F38\u4E24\u4E2A\u6307\u5934\u201D\u7684\u7EC6\u8282\uFF0C\u628A\u6781\u5EA6\u541D\u556C\u5199\u5F97\u5165\u6728\u4E09\u5206\u3002",
        example: "\u6311\u6389\u4E00\u830E\u706F\u8349\uFF0C\u4E25\u76D1\u751F\u8FD9\u624D\u653E\u5FC3\u5730\u70B9\u4E86\u70B9\u5934\uFF0C\u54BD\u4E86\u6C14\u3002",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F56F}\uFE0F", "\u270C\uFE0F", "\u{1F6CF}\uFE0F"], title: "\u4F38\u7740\u4E24\u4E2A\u6307\u5934\u4E0D\u54BD\u6C14", text: "\u5E8A\u4E0A\u4F38\u7740\u4E24\u4E2A\u6307\u5934\uFF0C\u662F\u5ACC\u4E24\u830E\u706F\u8349\u8D39\u6CB9\u3002" },
        check: { q: "\u4E25\u76D1\u751F\u4F38\u7740\u4E24\u4E2A\u6307\u5934\uFF0C\u5230\u5E95\u60F3\u8BF4\u4EC0\u4E48\uFF1F", options: ["\u706F\u76CF\u91CC\u70B9\u4E24\u830E\u706F\u8349\u592A\u8D39\u6CB9", "\u8FD8\u6709\u4E24\u4E2A\u4EB2\u4EBA\u6CA1\u89C1\u9762", "\u8FD8\u6709\u4E24\u7B14\u94F6\u5B50\u6CA1\u5429\u5490"], answer: 0 }
      }
    ],
    rhyme: "\u6454\u8DE4\u673A\u7075\u9760\u52A8\u4F5C\uFF0C\u8E66\u6765\u8E66\u53BB\u4E0B\u51B7\u7ECA\uFF1B\n\u7965\u5B50\u5065\u58EE\u5199\u5916\u8C8C\uFF0C\u94C1\u6247\u80F8\u6765\u76F4\u786C\u80CC\uFF1B\n\u4E24\u830E\u706F\u8349\u4E0D\u80AF\u706D\uFF0C\u4E00\u4E2A\u7EC6\u8282\u89C1\u541D\u556C\u3002",
    points: [
      "\u300A\u6454\u8DE4\u300B\uFF1A\u7528\u201C\u8E66\u6765\u8E66\u53BB\u3001\u4F7F\u5DE7\u62DB\u3001\u4E0B\u51B7\u7ECA\u5B50\u201D\u7B49\u52A8\u4F5C\u63CF\u5199\uFF0C\u5199\u51FA\u5C0F\u560E\u5B50\u7684\u673A\u7075\u3002",
      "\u201C\u4ED6\u50CF\u4E00\u68F5\u633A\u8131\u7684\u6811\u201D\uFF1A\u901A\u8FC7\u94C1\u6247\u9762\u4F3C\u7684\u80F8\u3001\u76F4\u786C\u7684\u80CC\u3001\u5BBD\u80A9\u7B49\u5916\u8C8C\u63CF\u5199\uFF0C\u8868\u73B0\u7965\u5B50\u7684\u5065\u58EE\u3002",
      "\u300A\u4E24\u830E\u706F\u8349\u300B\uFF1A\u6293\u4F4F\u201C\u4F38\u7740\u4E24\u4E2A\u6307\u5934\u201D\u7684\u7EC6\u8282\uFF0C\u5199\u51FA\u4E25\u76D1\u751F\u7684\u541D\u556C\u3002",
      "\u5199\u4EBA\u53EF\u4EE5\u7EFC\u5408\u8FD0\u7528\u52A8\u4F5C\u3001\u5916\u8C8C\u3001\u795E\u6001\u3001\u7EC6\u8282\u7B49\u63CF\u5199\uFF0C\u8BA9\u4EBA\u7269\u6D3B\u8D77\u6765\u3002"
    ],
    quiz: { q: "\u4E09\u7BC7\u77ED\u6587\u5206\u522B\u4FA7\u91CD\u7528\u4EC0\u4E48\u65B9\u6CD5\u5199\u4EBA\uFF1F", options: ["\u52A8\u4F5C\u3001\u5916\u8C8C\u3001\u7EC6\u8282\u63CF\u5199", "\u53EA\u5199\u5BF9\u8BDD", "\u53EA\u5199\u666F\u7269\u886C\u6258"], answer: 0 }
  },
  "chinese-g5-b-5-2": {
    example: "\u6CB3\u5317\u6709\u4E2A\u5237\u5899\u7684\u5E08\u5085\uFF0C\u5927\u5BB6\u53EB\u4ED6\u201C\u5237\u5B50\u674E\u201D\u3002\u4ED6\u5237\u6D46\u65F6\u5FC5\u7A7F\u4E00\u8EAB\u9ED1\uFF0C\u5E72\u5B8C\u6D3B\u8EAB\u4E0A\u7EDD\u6CA1\u6709\u4E00\u4E2A\u767D\u70B9\uFF0C\u8FD8\u7ACB\u4E0B\u89C4\u77E9\uFF1A\u53EA\u8981\u8EAB\u4E0A\u6709\u767D\u70B9\uFF0C\u767D\u5237\u4E0D\u8981\u94B1\u3002\u771F\u6709\u8FD9\u4E48\u795E\u5417\uFF1F\u6211\u4EEC\u8DDF\u7740\u5F92\u5F1F\u66F9\u5C0F\u4E09\u53BB\u77A7\u77A7\u3002",
    steps: [
      {
        title: "\u4E00\u8EAB\u9ED1\u8863\u7684\u89C4\u77E9",
        text: "\u5237\u5B50\u674E\u662F\u8425\u9020\u5382\u7684\u5E08\u5085\uFF0C\u4E13\u5E72\u7C89\u5237\u4E00\u884C\u3002\u4ED6\u5237\u7684\u5C4B\u5B50\uFF0C\u5C4B\u91CC\u4EC0\u4E48\u4E5F\u4E0D\u7528\u653E\uFF0C\u5355\u5750\u7740\u5C31\u5982\u540C\u5347\u5929\u4E00\u822C\u7F8E\u3002\u6700\u53EB\u4EBA\u53EB\u7EDD\u7684\u662F\u4ED6\u7684\u89C4\u77E9\uFF1A\u5237\u6D46\u5FC5\u7A7F\u4E00\u8EAB\u9ED1\uFF0C\u5E72\u5B8C\u6D3B\u8EAB\u4E0A\u7EDD\u6CA1\u6709\u4E00\u4E2A\u767D\u70B9\uFF1B\u53EA\u8981\u8EAB\u4E0A\u6709\u767D\u70B9\uFF0C\u767D\u5237\u4E0D\u8981\u94B1\u3002\u6562\u4E8E\u7ACB\u4E0B\u8FD9\u6837\u7684\u89C4\u77E9\uFF0C\u8BF4\u660E\u4ED6\u5BF9\u81EA\u5DF1\u7684\u624B\u827A\u6709\u591A\u81EA\u4FE1\u3002",
        example: "\u522B\u4EBA\u5237\u5899\u6015\u5F04\u810F\u8863\u670D\uFF0C\u5237\u5B50\u674E\u504F\u7A7F\u4E00\u8EAB\u9ED1\u2014\u2014\u767D\u70B9\u4E00\u4E2A\u90FD\u4E0D\u8BB8\u6709\uFF01",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F58C}\uFE0F", "\u2B1B", "\u{1F3E0}"], title: "\u7A7F\u9ED1\u8863\u5237\u767D\u5899", text: "\u5237\u6D46\u5FC5\u7A7F\u4E00\u8EAB\u9ED1\uFF0C\u6CBE\u4E0A\u767D\u70B9\u767D\u5237\u4E0D\u8981\u94B1\u3002" },
        check: { q: "\u5237\u5B50\u674E\u7ED9\u81EA\u5DF1\u7ACB\u4E0B\u4E86\u4EC0\u4E48\u89C4\u77E9\uFF1F", options: ["\u8EAB\u4E0A\u6709\u767D\u70B9\u5C31\u767D\u5237\u4E0D\u8981\u94B1", "\u6BCF\u5929\u53EA\u5237\u4E00\u9762\u5899", "\u5237\u5899\u65F6\u4E0D\u8BB8\u6709\u4EBA\u770B"], answer: 0 }
      },
      {
        title: "\u50CF\u5F39\u7434\u4E00\u6837\u5237\u5899",
        text: "\u90A3\u5929\u5237\u5B50\u674E\u7ED9\u4E00\u5EA7\u5927\u697C\u5237\u6D46\uFF0C\u5F92\u5F1F\u66F9\u5C0F\u4E09\u76F4\u633A\u633A\u7ACB\u5728\u95E8\u5916\u7B49\u7740\u770B\u3002\u5237\u5B50\u674E\u5237\u6D46\u65F6\uFF0C\u624B\u81C2\u60A0\u7136\u6446\u6765\u3001\u60A0\u7136\u6446\u53BB\uFF0C\u5982\u540C\u4F34\u7740\u9F13\u70B9\u3001\u548C\u7740\u7434\u97F3\uFF1B\u6BCF\u4E00\u6446\u5237\uFF0C\u5E26\u6D46\u7684\u6BDB\u5237\u5728\u5899\u9762\u556A\u5730\u6E05\u8106\u4E00\u54CD\uFF0C\u6781\u662F\u597D\u542C\u3002\u556A\u556A\u58F0\u91CC\uFF0C\u4E00\u9053\u9053\u6D46\u8854\u63A5\u5F97\u5929\u8863\u65E0\u7F1D\uFF0C\u5237\u8FC7\u53BB\u7684\u5899\u9762\uFF0C\u771F\u597D\u6BD4\u5E73\u5E73\u6574\u6574\u6253\u5F00\u4E00\u9762\u96EA\u767D\u7684\u5C4F\u969C\u3002\u66F9\u5C0F\u4E09\u4EB2\u773C\u89C1\u8BC6\u4E86\u5E08\u5085\u7684\u7EDD\u6D3B\u3002",
        example: "\u624B\u81C2\u4E00\u6446\u4E00\u6446\u50CF\u6307\u6325\u4E50\u961F\uFF0C\u5899\u9762\u5237\u8FC7\uFF0C\u96EA\u767D\u5E73\u6574\u5F97\u6CA1\u6709\u4E00\u4E1D\u7F1D\u3002",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F3B5}", "\u{1F58C}\uFE0F", "\u2728"], title: "\u4F34\u9F13\u70B9\u5237\u51FA\u7684\u767D\u5C4F\u969C", text: "\u6446\u81C2\u5982\u4F34\u9F13\u70B9\u7434\u97F3\uFF0C\u5899\u9762\u5316\u4F5C\u96EA\u767D\u5C4F\u969C\u3002" },
        check: { q: "\u5237\u5B50\u674E\u5237\u51FA\u7684\u5899\u9762\u50CF\u4EC0\u4E48\uFF1F", options: ["\u5E73\u5E73\u6574\u6574\u7684\u96EA\u767D\u5C4F\u969C", "\u82B1\u82B1\u7684\u8C03\u8272\u76D8", "\u6591\u6591\u70B9\u70B9\u7684\u5899\u7EB8"], answer: 0 }
      },
      {
        title: "\u90A3\u4E2A\u201C\u767D\u70B9\u201D\u7684\u79D8\u5BC6",
        text: "\u5237\u5B8C\u5899\uFF0C\u5237\u5B50\u674E\u8EAB\u4E0A\u5E72\u5E72\u51C0\u51C0\uFF0C\u679C\u7136\u6CA1\u6709\u4E00\u4E2A\u767D\u70B9\u3002\u53EF\u66F9\u5C0F\u4E09\u5FFD\u7136\u53D1\u73B0\uFF1A\u5E08\u5085\u88E4\u5B50\u4E0A\u6709\u4E2A\u767D\u70B9\uFF01\u4ED6\u5FC3\u91CC\u4E00\u60CA\uFF1A\u5E08\u5085\u4E0D\u662F\u8BF4\u6709\u767D\u70B9\u767D\u5237\u4E0D\u8981\u94B1\u5417\uFF1F\u5237\u5B50\u674E\u4F4E\u5934\u4E00\u770B\u7B11\u4E86\uFF0C\u62AC\u624B\u628A\u201C\u767D\u70B9\u201D\u5F39\u6389\u2014\u2014\u539F\u6765\u90A3\u662F\u4E00\u4E2A\u88AB\u9999\u70DF\u70E7\u51FA\u6765\u7684\u5C0F\u6D1E\uFF0C\u4ECE\u6D1E\u91CC\u9732\u51FA\u767D\u8272\u7684\u886C\u88E4\u3002\u66F9\u5C0F\u4E09\u5B66\u5F92\u7684\u5934\u4E00\u5929\uFF0C\u89C1\u5230\u3001\u542C\u5230\u3001\u5B66\u5230\u7684\uFF0C\u6050\u6015\u522B\u4EBA\u4E00\u8F88\u5B50\u4E5F\u4E0D\u4E00\u5B9A\u660E\u767D\u5462\u3002",
        example: "\u865A\u60CA\u4E00\u573A\uFF01\u90A3\u4E2A\u201C\u767D\u70B9\u201D\u4E0D\u662F\u767D\u6D46\uFF0C\u662F\u70DF\u6D1E\u91CC\u7684\u767D\u886C\u88E4\u3002",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F456}", "\u{1F6AC}", "\u{1F50D}"], title: "\u88E4\u5B50\u4E0A\u7684\u201C\u767D\u70B9\u201D", text: "\u88E4\u5B50\u201C\u767D\u70B9\u201D\u539F\u662F\u70DF\u6D1E\uFF0C\u9732\u51FA\u767D\u8272\u886C\u88E4\u3002" },
        check: { q: "\u5E08\u5085\u88E4\u5B50\u4E0A\u90A3\u4E2A\u201C\u767D\u70B9\u201D\u5230\u5E95\u662F\u4EC0\u4E48\uFF1F", options: ["\u70DF\u70E7\u51FA\u7684\u5C0F\u6D1E\u9732\u51FA\u767D\u886C\u88E4", "\u6CA1\u5237\u5E72\u51C0\u7684\u6D46", "\u4E0D\u5C0F\u5FC3\u8E6D\u4E0A\u7684\u7070"], answer: 0 }
      }
    ],
    rhyme: "\u5237\u5B50\u674E\uFF0C\u7A7F\u9ED1\u8863\uFF0C\u7ACB\u4E0B\u89C4\u77E9\u4E0D\u8BB8\u767D\uFF1B\n\u6446\u81C2\u5237\u5899\u50CF\u5F39\u7434\uFF0C\u5899\u9762\u5982\u96EA\u767D\u5C4F\u969C\uFF1B\n\u88E4\u4E0A\u201C\u767D\u70B9\u201D\u539F\u662F\u6D1E\uFF0C\u7EDD\u6D3B\u80CC\u540E\u662F\u529F\u592B\u3002",
    points: [
      "\u5237\u5B50\u674E\u7684\u89C4\u77E9\uFF1A\u5237\u6D46\u7A7F\u4E00\u8EAB\u9ED1\uFF0C\u8EAB\u4E0A\u6709\u767D\u70B9\u5C31\u767D\u5237\u4E0D\u8981\u94B1\uFF0C\u8DB3\u89C1\u4ED6\u6280\u827A\u9AD8\u8D85\u3001\u5145\u6EE1\u81EA\u4FE1\u3002",
      "\u5237\u5899\u52A8\u4F5C\u201C\u5982\u540C\u4F34\u7740\u9F13\u70B9\uFF0C\u548C\u7740\u7434\u97F3\u201D\uFF0C\u5899\u9762\u201C\u50CF\u6253\u5F00\u4E00\u9762\u96EA\u767D\u7684\u5C4F\u969C\u201D\uFF0C\u5199\u51FA\u52A8\u4F5C\u7684\u7F8E\u4E0E\u6280\u827A\u7684\u7CBE\u3002",
      "\u7ED3\u5C3E\u7684\u201C\u767D\u70B9\u201D\u539F\u6765\u662F\u88AB\u70DF\u70E7\u51FA\u7684\u5C0F\u6D1E\uFF0C\u4E0D\u662F\u767D\u6D46\uFF0C\u51FA\u4EBA\u610F\u6599\u53C8\u5728\u60C5\u7406\u4E4B\u4E2D\u3002",
      "\u7528\u5F92\u5F1F\u66F9\u5C0F\u4E09\u201C\u534A\u4FE1\u534A\u7591\u2192\u4EB2\u773C\u76EE\u7779\u2192\u865A\u60CA\u4E00\u573A\u201D\u7684\u6240\u89C1\u6240\u611F\uFF0C\u4ECE\u4FA7\u9762\u70D8\u6258\u5237\u5B50\u674E\u7684\u9AD8\u8D85\u6280\u827A\u3002"
    ],
    quiz: { q: "\u66F9\u5C0F\u4E09\u8DDF\u5E08\u5085\u5B66\u5230\u7684\u201C\u5934\u4E00\u5929\u201D\u6700\u8BA9\u4ED6\u660E\u767D\u4EC0\u4E48\uFF1F", options: ["\u624B\u827A\u7684\u9AD8\u8D85\u9760\u771F\u529F\u592B\uFF0C\u4E5F\u61C2\u4E86\u505A\u4EBA\u7684\u9053\u7406", "\u5237\u5899\u53EF\u4EE5\u5077\u61D2\u53D6\u5DE7", "\u7A7F\u9ED1\u8863\u670D\u5C31\u4E0D\u4F1A\u5F04\u810F"], answer: 0 }
  },
  /* ------------------------------ 第六单元 ------------------------------ */
  "chinese-g5-b-6-1": {
    example: "\u96C6\u5E02\u4E0A\uFF0C\u4E00\u4E2A\u695A\u56FD\u4EBA\u4E00\u624B\u4E3E\u7740\u76FE\u3001\u4E00\u624B\u4E3E\u7740\u77DB\uFF0C\u5927\u58F0\u53EB\u5356\u3002\u4ED6\u5938\u76FE\u201C\u4EC0\u4E48\u4E5F\u523A\u4E0D\u7A7F\u201D\uFF0C\u53C8\u5938\u77DB\u201C\u4EC0\u4E48\u90FD\u80FD\u523A\u7A7F\u201D\u3002\u53EF\u662F\u6709\u4EBA\u95EE\u4E86\u4E00\u53E5\u8BDD\uFF0C\u4ED6\u7ACB\u523B\u7B54\u4E0D\u4E0A\u6765\u3002\u8FD9\u662F\u600E\u4E48\u56DE\u4E8B\uFF1F\u6211\u4EEC\u8BFB\u4E00\u8BFB\u8FD9\u5219\u6587\u8A00\u6587\u300A\u81EA\u76F8\u77DB\u76FE\u300B\u3002",
    steps: [
      {
        title: "\u5938\u76FE\u53C8\u5938\u77DB",
        text: "\u695A\u4EBA\u6709\u9B3B\u76FE\u4E0E\u77DB\u8005\u2014\u2014\u695A\u56FD\u6709\u4E2A\u5356\u76FE\u548C\u77DB\u7684\u4EBA\u3002\u4ED6\u5938\u8000\u81EA\u5DF1\u7684\u76FE\u8BF4\uFF1A\u201C\u543E\u76FE\u4E4B\u575A\uFF0C\u7269\u83AB\u80FD\u9677\u4E5F\u3002\u201D\u6211\u7684\u76FE\u975E\u5E38\u575A\u56FA\uFF0C\u4EC0\u4E48\u4E1C\u897F\u90FD\u523A\u4E0D\u7A7F\u3002\u63A5\u7740\u53C8\u5938\u8000\u4ED6\u7684\u77DB\u8BF4\uFF1A\u201C\u543E\u77DB\u4E4B\u5229\uFF0C\u4E8E\u7269\u65E0\u4E0D\u9677\u4E5F\u3002\u201D\u6211\u7684\u77DB\u975E\u5E38\u950B\u5229\uFF0C\u4EC0\u4E48\u4E1C\u897F\u90FD\u80FD\u523A\u7A7F\u3002\u53C8\u662F\u201C\u83AB\u80FD\u9677\u201D\uFF0C\u53C8\u662F\u201C\u65E0\u4E0D\u9677\u201D\uFF0C\u542C\u8D77\u6765\u53EF\u5389\u5BB3\u4E86\u3002",
        example: "\u201C\u6211\u7684\u76FE\uFF0C\u4EC0\u4E48\u4E5F\u523A\u4E0D\u7A7F\uFF01\u201D\u201C\u6211\u7684\u77DB\uFF0C\u4EC0\u4E48\u90FD\u80FD\u523A\u7A7F\uFF01\u201D",
        figure: { type: "scene", bg: "city", emojis: ["\u{1F6E1}\uFE0F", "\u{1F5E1}\uFE0F", "\u{1F9D4}"], title: "\u5356\u76FE\u53C8\u5356\u77DB\u7684\u695A\u4EBA", text: "\u96C6\u5E02\u4E0A\u695A\u4EBA\u53EB\u5356\uFF1A\u76FE\u83AB\u80FD\u9677\uFF0C\u77DB\u65E0\u4E0D\u9677\u3002" },
        check: { q: "\u695A\u4EBA\u5938\u81EA\u5DF1\u7684\u76FE\u600E\u4E48\u6837\uFF1F", options: ["\u575A\u56FA\uFF0C\u4EC0\u4E48\u4E5F\u523A\u4E0D\u7A7F", "\u950B\u5229\uFF0C\u4EC0\u4E48\u90FD\u80FD\u523A\u7A7F", "\u53C8\u8F7B\u53C8\u597D\u62FF"], answer: 0 }
      },
      {
        title: "\u4E00\u53E5\u8BDD\u95EE\u4F4F\u4E86",
        text: "\u6709\u4EBA\u95EE\u4ED6\uFF1A\u201C\u4EE5\u5B50\u4E4B\u77DB\uFF0C\u9677\u5B50\u4E4B\u76FE\uFF0C\u4F55\u5982\uFF1F\u201D\u2014\u2014\u7528\u4F60\u7684\u77DB\u53BB\u523A\u4F60\u7684\u76FE\uFF0C\u7ED3\u679C\u4F1A\u600E\u4E48\u6837\u5462\uFF1F\u695A\u4EBA\u201C\u5F17\u80FD\u5E94\u4E5F\u201D\uFF0C\u4E00\u53E5\u8BDD\u4E5F\u56DE\u7B54\u4E0D\u4E0A\u6765\u3002\u56E0\u4E3A\u4ED6\u7684\u76FE\u8BF4\u201C\u4EC0\u4E48\u90FD\u523A\u4E0D\u7A7F\u201D\uFF0C\u4ED6\u7684\u77DB\u53C8\u8BF4\u201C\u4EC0\u4E48\u90FD\u80FD\u523A\u7A7F\u201D\uFF0C\u8FD9\u4E24\u53E5\u8BDD\u653E\u5728\u4E00\u8D77\uFF0C\u5C31\u81EA\u5DF1\u6253\u81EA\u5DF1\u7684\u5634\u5DF4\u4E86\u3002",
        example: "\u56F4\u89C2\u7684\u4EBA\u95EE\uFF1A\u201C\u62FF\u4F60\u7684\u77DB\uFF0C\u523A\u4F60\u7684\u76FE\uFF0C\u884C\u4E0D\u884C\uFF1F\u201D\u5356\u8D27\u4EBA\u5F20\u5F20\u5634\uFF0C\u7B54\u4E0D\u4E0A\u6765\u4E86\u3002",
        figure: { type: "scene", bg: "city", emojis: ["\u{1F914}", "\u{1F6E1}\uFE0F", "\u{1F5E1}\uFE0F"], title: "\u77DB\u4E0E\u76FE\u6BD4\u4E00\u6BD4", text: "\u201C\u4EE5\u5B50\u4E4B\u77DB\u9677\u5B50\u4E4B\u76FE\u201D\u4E00\u95EE\uFF0C\u695A\u4EBA\u7B54\u4E0D\u4E0A\u6765\u3002" },
        check: { q: "\u201C\u4EE5\u5B50\u4E4B\u77DB\uFF0C\u9677\u5B50\u4E4B\u76FE\u201D\u4F1A\u600E\u6837\uFF1F", options: ["\u77DB\u548C\u76FE\u7684\u4E24\u79CD\u8BF4\u6CD5\u4E92\u76F8\u62B5\u89E6\uFF0C\u7B54\u4E0D\u4E0A\u6765", "\u76FE\u4E00\u5B9A\u88AB\u523A\u7A7F", "\u77DB\u4E00\u5B9A\u88AB\u6298\u65AD"], answer: 0 }
      },
      {
        title: "\u524D\u540E\u8981\u4E00\u81F4\u7684\u9053\u7406",
        text: "\u6545\u4E8B\u6700\u540E\u8BF4\uFF1A\u201C\u592B\u4E0D\u53EF\u9677\u4E4B\u76FE\u4E0E\u65E0\u4E0D\u9677\u4E4B\u77DB\uFF0C\u4E0D\u53EF\u540C\u4E16\u800C\u7ACB\u3002\u201D\u2014\u2014\u4EC0\u4E48\u4E5F\u523A\u4E0D\u7A7F\u7684\u76FE\u548C\u4EC0\u4E48\u90FD\u80FD\u523A\u7A7F\u7684\u77DB\uFF0C\u4E0D\u53EF\u80FD\u540C\u65F6\u5B58\u5728\u3002\u8BF4\u8BDD\u3001\u505A\u4E8B\u90FD\u8981\u5B9E\u4E8B\u6C42\u662F\uFF0C\u524D\u540E\u4E00\u81F4\uFF0C\u4E0D\u80FD\u50CF\u8FD9\u4E2A\u695A\u4EBA\u4E00\u6837\u5938\u5927\u5176\u8BCD\uFF0C\u81EA\u5DF1\u8DDF\u81EA\u5DF1\u5531\u53CD\u8C03\u3002\u6210\u8BED\u201C\u81EA\u76F8\u77DB\u76FE\u201D\u5C31\u7528\u6765\u6BD4\u55BB\u8BF4\u8BDD\u505A\u4E8B\u524D\u540E\u62B5\u89E6\u3002",
        example: "\u5356\u8D27\u65F6\u628A\u8BDD\u8BF4\u8FC7\u5934\uFF0C\u522B\u4EBA\u4E00\u53E5\u53CD\u95EE\uFF0C\u8C0E\u8A00\u5C31\u9732\u9985\u4E86\u3002",
        figure: { type: "scene", bg: "city", emojis: ["\u2696\uFE0F", "\u{1F5E3}\uFE0F", "\u{1F9E0}"], title: "\u524D\u540E\u4E00\u81F4\u624D\u53EF\u4FE1", text: "\u8BF4\u8BDD\u505A\u4E8B\u524D\u540E\u8981\u4E00\u81F4\uFF0C\u5B9E\u4E8B\u6C42\u662F\u624D\u53EF\u4FE1\u3002" },
        check: { q: "\u8FD9\u5219\u5BD3\u8A00\u544A\u8BC9\u6211\u4EEC\u4EC0\u4E48\u9053\u7406\uFF1F", options: ["\u8BF4\u8BDD\u505A\u4E8B\u8981\u524D\u540E\u4E00\u81F4\uFF0C\u5B9E\u4E8B\u6C42\u662F", "\u77DB\u6BD4\u76FE\u66F4\u5389\u5BB3", "\u5356\u4E1C\u897F\u8981\u591A\u5938\u51E0\u53E5"], answer: 0 }
      }
    ],
    rhyme: "\u695A\u4EBA\u5356\u77DB\u53C8\u5356\u76FE\uFF0C\u76FE\u575A\u77DB\u5229\u90FD\u5938\u904D\uFF1B\n\u201C\u4EE5\u5B50\u4E4B\u77DB\u9677\u5B50\u4E4B\u76FE\u201D\uFF0C\u54D1\u53E3\u65E0\u8A00\u96BE\u5E94\u7B54\uFF1B\n\u8BF4\u8BDD\u524D\u540E\u8981\u4E00\u81F4\uFF0C\u81EA\u76F8\u77DB\u76FE\u95F9\u7B11\u8BDD\u3002",
    points: [
      "\u91CD\u70B9\u8BCD\u53E5\uFF1A\u9B3B\uFF08\u5356\uFF09\u3001\u8A89\uFF08\u5938\u8000\uFF09\u3001\u9677\uFF08\u523A\u7A7F\uFF09\u3001\u5F17\u80FD\u5E94\uFF08\u7B54\u4E0D\u4E0A\u6765\uFF09\u3001\u540C\u4E16\u800C\u7ACB\uFF08\u540C\u65F6\u5B58\u5728\uFF09\u3002",
      "\u695A\u4EBA\u5938\u76FE\u201C\u7269\u83AB\u80FD\u9677\u201D\uFF0C\u53C8\u5938\u77DB\u201C\u4E8E\u7269\u65E0\u4E0D\u9677\u201D\uFF0C\u4E24\u79CD\u8BF4\u6CD5\u4E92\u76F8\u62B5\u89E6\u3002",
      "\u201C\u4EE5\u5B50\u4E4B\u77DB\uFF0C\u9677\u5B50\u4E4B\u76FE\uFF0C\u4F55\u5982\u201D\u4E00\u53E5\uFF0C\u95EE\u5F97\u695A\u4EBA\u54D1\u53E3\u65E0\u8A00\u3002",
      "\u5BD3\u610F\uFF1A\u8BF4\u8BDD\u3001\u505A\u4E8B\u8981\u524D\u540E\u4E00\u81F4\uFF0C\u4E0D\u80FD\u81EA\u76F8\u62B5\u89E6\uFF1B\u6210\u8BED\u201C\u81EA\u76F8\u77DB\u76FE\u201D\u7531\u6B64\u800C\u6765\u3002"
    ],
    quiz: { q: "\u6210\u8BED\u201C\u81EA\u76F8\u77DB\u76FE\u201D\u7528\u6765\u6BD4\u55BB\u4EC0\u4E48\uFF1F", options: ["\u8BF4\u8BDD\u505A\u4E8B\u524D\u540E\u62B5\u89E6\uFF0C\u4E92\u76F8\u6253\u67B6", "\u6B66\u5668\u5F88\u5389\u5BB3", "\u505A\u751F\u610F\u5F88\u8BDA\u5B9E"], answer: 0 }
  },
  "chinese-g5-b-6-2": {
    example: "\u9F50\u56FD\u5927\u5C06\u7530\u5FCC\u5F88\u559C\u6B22\u8D5B\u9A6C\uFF0C\u53EF\u4E00\u8FDE\u4E09\u573A\u90FD\u8F93\u7ED9\u4E86\u9F50\u5A01\u738B\uFF0C\u5782\u5934\u4E27\u6C14\u6B63\u8981\u79BB\u5F00\u3002\u8FD9\u65F6\u597D\u670B\u53CB\u5B59\u8191\u53EB\u4F4F\u4ED6\uFF1A\u201C\u6211\u6709\u529E\u6CD5\u8BA9\u4F60\u53D6\u80DC\uFF0C\u4E00\u5339\u9A6C\u4E5F\u4E0D\u7528\u6362\u3002\u201D\u4E0D\u6362\u9A6C\u4E5F\u80FD\u8D62\uFF1F\u6211\u4EEC\u770B\u770B\u5B59\u8191\u7684\u5999\u8BA1\u3002",
    steps: [
      {
        title: "\u540C\u7B49\u7EA7\u8F83\u91CF\uFF0C\u4E09\u573A\u5168\u8F93",
        text: "\u7530\u5FCC\u548C\u9F50\u5A01\u738B\u8D5B\u9A6C\uFF0C\u628A\u5404\u81EA\u7684\u9A6C\u5206\u6210\u4E0A\u3001\u4E2D\u3001\u4E0B\u4E09\u7B49\uFF0C\u6BD4\u8D5B\u65F6\u4E0A\u7B49\u5BF9\u4E0A\u7B49\u3001\u4E2D\u7B49\u5BF9\u4E2D\u7B49\u3001\u4E0B\u7B49\u5BF9\u4E0B\u7B49\u3002\u9F50\u5A01\u738B\u6BCF\u4E2A\u7B49\u7EA7\u7684\u9A6C\u90FD\u6BD4\u7530\u5FCC\u7684\u5F3A\uFF0C\u6240\u4EE5\u4E09\u573A\u4E0B\u6765\u7530\u5FCC\u90FD\u5931\u8D25\u4E86\u3002\u4ED6\u89C9\u5F97\u626B\u5174\uFF0C\u5782\u5934\u4E27\u6C14\u5730\u51C6\u5907\u79BB\u5F00\u8D5B\u573A\u3002",
        example: "\u4E0A\u5BF9\u4E0A\u3001\u4E2D\u5BF9\u4E2D\u3001\u4E0B\u5BF9\u4E0B\uFF0C\u9F50\u5A01\u738B\u7684\u9A6C\u6BCF\u4E00\u7B49\u90FD\u5FEB\u4E00\u70B9\uFF0C\u7530\u5FCC\u4E09\u573A\u5168\u8F93\u3002",
        figure: { type: "scene", bg: "field", emojis: ["\u{1F40E}", "\u{1F3C1}", "\u{1F61E}"], title: "\u4E09\u573A\u7686\u8F93\u7684\u7530\u5FCC", text: "\u540C\u7B49\u7EA7\u8F83\u91CF\u573A\u573A\u8F93\uFF0C\u7530\u5FCC\u5782\u5934\u4E27\u6C14\u3002" },
        check: { q: "\u7530\u5FCC\u7B2C\u4E00\u56DE\u8D5B\u9A6C\u4E3A\u4EC0\u4E48\u4E09\u573A\u90FD\u8F93\uFF1F", options: ["\u9F50\u5A01\u738B\u6BCF\u4E2A\u7B49\u7EA7\u7684\u9A6C\u90FD\u6BD4\u7530\u5FCC\u7684\u5F3A", "\u7530\u5FCC\u7684\u9A6C\u751F\u75C5\u4E86", "\u8D5B\u9A6C\u65F6\u4E0B\u5927\u96E8"], answer: 0 }
      },
      {
        title: "\u5B59\u8191\u7684\u9526\u56CA\u5999\u8BA1",
        text: "\u5B59\u8191\u62CD\u62CD\u7530\u5FCC\u7684\u80A9\u8180\uFF0C\u8BF4\u9F50\u5A01\u738B\u7684\u9A6C\u5176\u5B9E\u6BD4\u4ED6\u7684\u5FEB\u4E0D\u4E86\u591A\u5C11\uFF0C\u518D\u8D5B\u4E00\u6B21\u6709\u529E\u6CD5\u8D62\u3002\u7530\u5FCC\u7591\u60D1\uFF1A\u4F60\u662F\u8BF4\u53E6\u6362\u51E0\u5339\u9A6C\uFF1F\u5B59\u8191\u6447\u5934\uFF1A\u201C\u4E00\u5339\u4E5F\u4E0D\u7528\u6362\u3002\u201D\u4ED6\u8BA9\u7530\u5FCC\u7167\u4ED6\u7684\u4E3B\u610F\u529E\uFF0C\u800C\u4E14\u80F8\u6709\u6210\u7AF9\u3002\u6BD4\u8D5B\u5F00\u59CB\uFF1A\u7B2C\u4E00\u573A\uFF0C\u7530\u5FCC\u7528\u4E0B\u7B49\u9A6C\u5BF9\u9F50\u5A01\u738B\u7684\u4E0A\u7B49\u9A6C\uFF0C\u8F93\u4E86\uFF1B\u7B2C\u4E8C\u573A\uFF0C\u7528\u4E0A\u7B49\u9A6C\u5BF9\u9F50\u5A01\u738B\u7684\u4E2D\u7B49\u9A6C\uFF0C\u8D62\u4E86\uFF1B\u7B2C\u4E09\u573A\uFF0C\u7528\u4E2D\u7B49\u9A6C\u5BF9\u9F50\u5A01\u738B\u7684\u4E0B\u7B49\u9A6C\uFF0C\u53C8\u8D62\u4E86\u3002",
        example: "\u4E0B\u7B49\u9A6C\u53BB\u78B0\u6700\u5F3A\u7684\u4E0A\u7B49\u9A6C\uFF0C\u6545\u610F\u8F93\u4E00\u573A\uFF0C\u628A\u597D\u94A2\u7528\u5728\u5200\u5203\u4E0A\u3002",
        figure: { type: "scene", bg: "field", emojis: ["\u{1F40E}", "\u{1F9E0}", "\u{1F0CF}"], title: "\u8C03\u6362\u51FA\u573A\u987A\u5E8F", text: "\u5B59\u8191\u732E\u7B56\uFF1A\u4E0B\u7B49\u9A6C\u78B0\u5F3A\u4E0A\u7B49\u9A6C\uFF0C\u8C03\u6362\u987A\u5E8F\u3002" },
        check: { q: "\u5B59\u8191\u8BA9\u7530\u5FCC\u600E\u4E48\u5B89\u6392\u51FA\u573A\u987A\u5E8F\uFF1F", options: ["\u4E0B\u5BF9\u4E0A\u4E00\u573A\uFF0C\u518D\u4E0A\u5BF9\u4E2D\u3001\u4E2D\u5BF9\u4E0B", "\u4E0A\u5BF9\u4E0A\u3001\u4E2D\u5BF9\u4E2D\u3001\u4E0B\u5BF9\u4E0B", "\u6BCF\u6B21\u90FD\u6D3E\u6700\u5FEB\u7684\u9A6C"], answer: 0 }
      },
      {
        title: "\u8F6C\u8D25\u4E3A\u80DC\u7684\u667A\u6167",
        text: "\u6BD4\u8D5B\u7ED3\u679C\u662F\u7530\u5FCC\u80DC\u4E24\u573A\u8F93\u4E00\u573A\uFF0C\u8D62\u4E86\u9F50\u5A01\u738B\uFF0C\u9F50\u5A01\u738B\u770B\u5F97\u76EE\u77AA\u53E3\u5446\u3002\u8FD8\u662F\u539F\u6765\u7684\u9A6C\uFF0C\u53EA\u8C03\u6362\u4E86\u4E00\u4E0B\u51FA\u573A\u987A\u5E8F\uFF0C\u5C31\u80FD\u8F6C\u8D25\u4E3A\u80DC\u3002\u5B59\u8191\u53D6\u80DC\u9760\u7684\u4E0D\u662F\u86EE\u529B\uFF0C\u800C\u662F\u4ED4\u7EC6\u89C2\u5BDF\uFF1A\u9F50\u5A01\u738B\u7684\u9A6C\u53EA\u662F\u201C\u5FEB\u4E0D\u4E86\u591A\u5C11\u201D\uFF0C\u7528\u81EA\u5DF1\u6700\u5F31\u7684\u4E0B\u7B49\u9A6C\u53BB\u6D88\u8017\u5BF9\u65B9\u6700\u5F3A\u7684\u4E0A\u7B49\u9A6C\uFF0C\u518D\u8BA9\u4E0A\u7B49\u9A6C\u3001\u4E2D\u7B49\u9A6C\u53BB\u8D62\u5BF9\u65B9\u7684\u4E2D\u7B49\u9A6C\u3001\u4E0B\u7B49\u9A6C\u2014\u2014\u8FD9\u5C31\u662F\u626C\u957F\u907F\u77ED\u3001\u7EDF\u7B79\u5B89\u6392\u3002",
        example: "\u727A\u7272\u4E00\u5339\u4E0B\u7B49\u9A6C\uFF0C\u6362\u6765\u4E24\u573A\u80DC\u5229\u2014\u2014\u61C2\u5F97\u53D6\u820D\u624D\u80FD\u8D62\u3002",
        figure: { type: "scene", bg: "field", emojis: ["\u{1F3C6}", "\u{1F389}", "\u{1F40E}"], title: "\u4E24\u80DC\u4E00\u8D1F\u8F6C\u8D25\u4E3A\u80DC", text: "\u626C\u957F\u907F\u77ED\u8C03\u987A\u5E8F\uFF0C\u4E24\u80DC\u4E00\u8D1F\u5DE7\u53D6\u80DC\u3002" },
        check: { q: "\u5B59\u8191\u53D6\u80DC\u7684\u79D8\u8BC0\u662F\u4EC0\u4E48\uFF1F", options: ["\u53EA\u8C03\u6362\u51FA\u573A\u987A\u5E8F\uFF0C\u626C\u957F\u907F\u77ED", "\u5077\u5077\u6362\u4E86\u66F4\u5F3A\u7684\u9A6C", "\u8BA9\u9F50\u5A01\u738B\u8BA9\u8D5B"], answer: 0 }
      }
    ],
    rhyme: "\u7530\u5FCC\u8D5B\u9A6C\u4E09\u8FDE\u8F93\uFF0C\u5782\u5934\u4E27\u6C14\u60F3\u56DE\u5BB6\uFF1B\n\u5B59\u8191\u51FA\u8C0B\u5212\u987A\u5E8F\uFF0C\u5F31\u9A6C\u53BB\u78B0\u5F3A\u4E0A\u7B49\uFF1B\n\u4E0A\u5BF9\u4E2D\u6765\u4E2D\u5BF9\u4E0B\uFF0C\u4E24\u80DC\u4E00\u8D1F\u5DE7\u53D6\u80DC\u3002",
    points: [
      "\u5B59\u8191\u4ED4\u7EC6\u89C2\u5BDF\uFF0C\u53D1\u73B0\u9F50\u5A01\u738B\u7684\u9A6C\u53EA\u662F\u201C\u5FEB\u4E0D\u4E86\u591A\u5C11\u201D\u3002",
      "\u7B56\u7565\uFF1A\u4E0B\u7B49\u9A6C\u5BF9\u9F50\u5A01\u738B\u7684\u4E0A\u7B49\u9A6C\uFF0C\u4E0A\u7B49\u9A6C\u5BF9\u4E2D\u7B49\u9A6C\uFF0C\u4E2D\u7B49\u9A6C\u5BF9\u4E0B\u7B49\u9A6C\u3002",
      "\u6BD4\u8D5B\u7ED3\u679C\uFF1A\u7530\u5FCC\u80DC\u4E24\u573A\u8F93\u4E00\u573A\uFF0C\u8D62\u4E86\u9F50\u5A01\u738B\u3002",
      "\u9053\u7406\uFF1A\u505A\u4E8B\u8981\u5584\u4E8E\u89C2\u5BDF\u5206\u6790\u3001\u626C\u957F\u907F\u77ED\u3001\u7EDF\u7B79\u5B89\u6392\uFF0C\u5C31\u80FD\u8F6C\u8D25\u4E3A\u80DC\u3002"
    ],
    quiz: { q: "\u7530\u5FCC\u8FD8\u662F\u539F\u6765\u7684\u9A6C\uFF0C\u4E3A\u4EC0\u4E48\u80FD\u8D62\uFF1F", options: ["\u8C03\u6362\u4E86\u51FA\u573A\u987A\u5E8F\uFF0C\u7528\u7B56\u7565\u53D6\u80DC", "\u9A6C\u7A81\u7136\u8DD1\u5F97\u66F4\u5FEB\u4E86", "\u9F50\u5A01\u738B\u6545\u610F\u653E\u6C34"], answer: 0 }
  },
  "chinese-g5-b-6-3": {
    example: "\u4E00\u8258\u73AF\u6E38\u4E16\u754C\u7684\u5E06\u8239\u6B63\u5728\u5F80\u56DE\u822A\u884C\u3002\u7532\u677F\u4E0A\uFF0C\u4E00\u53EA\u7334\u5B50\u628A\u8239\u957F\u7684\u513F\u5B50\u9017\u5F97\u4E0A\u4E86\u6845\u6746\uFF0C\u5B69\u5B50\u7AD9\u4E0A\u6700\u9AD8\u7684\u6A2A\u6728\uFF0C\u968F\u65F6\u53EF\u80FD\u6454\u4E0B\u6765\uFF01\u8FD9\u65F6\u8239\u957F\u62FF\u7740\u67AA\u8D70\u51FA\u8239\u8231\u2026\u2026\u8FD9\u60CA\u9669\u7684\u4E00\u5E55\uFF0C\u5C31\u662F\u6258\u5C14\u65AF\u6CF0\u5199\u7684\u300A\u8DF3\u6C34\u300B\u3002",
    steps: [
      {
        title: "\u653E\u8086\u7684\u7334\u5B50",
        text: "\u8FD9\u4E00\u5929\u98CE\u5E73\u6D6A\u9759\uFF0C\u6C34\u624B\u4EEC\u90FD\u5728\u7532\u677F\u4E0A\u3002\u4E00\u53EA\u7334\u5B50\u5728\u4EBA\u7FA4\u91CC\u94BB\u6765\u94BB\u53BB\uFF0C\u6A21\u4EFF\u4EBA\u7684\u52A8\u4F5C\uFF0C\u60F9\u5F97\u5927\u5BB6\u54C8\u54C8\u5927\u7B11\u3002\u5B83\u77E5\u9053\u5927\u5BB6\u62FF\u5B83\u53D6\u4E50\uFF0C\u5C31\u66F4\u52A0\u653E\u8086\uFF1A\u5FFD\u7136\u8DF3\u5230\u8239\u957F\u513F\u5B50\u9762\u524D\uFF0C\u6458\u4E0B\u4ED6\u7684\u5E3D\u5B50\u6234\u5728\u81EA\u5DF1\u5934\u4E0A\uFF0C\u5F88\u5FEB\u722C\u4E0A\u6845\u6746\uFF0C\u628A\u5E3D\u5B50\u6302\u5230\u6700\u9AD8\u7684\u6A2A\u6728\u4E00\u5934\uFF0C\u8FD8\u5750\u5728\u6845\u6746\u9876\u7AEF\uFF0C\u626D\u7740\u8EAB\u5B50\u3001\u9F87\u7259\u54A7\u5634\u505A\u602A\u6837\u3002",
        example: "\u7334\u5B50\u62A2\u8D70\u5E3D\u5B50\uFF0C\u564C\u564C\u722C\u4E0A\u6845\u6746\uFF0C\u628A\u5E3D\u5B50\u9AD8\u9AD8\u6302\u8D77\u3002",
        figure: { type: "scene", bg: "water", emojis: ["\u{1F412}", "\u{1F3A9}", "\u26F5"], title: "\u62A2\u5E3D\u5B50\u7684\u7334\u5B50", text: "\u7334\u5B50\u62A2\u5E3D\u5B50\u722C\u4E0A\u6845\u6746\uFF0C\u5B69\u5B50\u6C14\u6781\u53BB\u8FFD\u3002" },
        check: { q: "\u5B69\u5B50\u4E3A\u4EC0\u4E48\u8981\u722C\u4E0A\u6845\u6746\uFF1F", options: ["\u6C14\u6781\u4E86\uFF0C\u8981\u53BB\u8FFD\u7334\u5B50\u62FF\u56DE\u5E3D\u5B50", "\u60F3\u770B\u770B\u8FDC\u5904\u7684\u5927\u6D77", "\u7334\u5B50\u8BF7\u4ED6\u53BB\u505A\u5BA2"], answer: 0 }
      },
      {
        title: "\u6A2A\u6728\u4E0A\u7684\u5371\u9669",
        text: "\u5B69\u5B50\u6C14\u6781\u4E86\uFF0C\u4E22\u5F00\u6845\u6746\u8D70\u4E0A\u6A2A\u6728\u53BB\u8FFD\u7334\u5B50\uFF0C\u4E00\u76F4\u8FFD\u5230\u6700\u9AD8\u7684\u6A2A\u6728\u4E0A\u3002\u8FD9\u65F6\u5019\uFF0C\u6C34\u624B\u4EEC\u5168\u90FD\u5413\u5446\u4E86\uFF1A\u5B69\u5B50\u53EA\u8981\u4E00\u5931\u8DB3\uFF0C\u76F4\u6454\u5230\u7532\u677F\u4E0A\u5C31\u6CA1\u547D\u4E86\uFF1B\u5C31\u7B97\u8D70\u5230\u6A2A\u6728\u90A3\u5934\u62FF\u5230\u5E3D\u5B50\uFF0C\u4E5F\u96BE\u4EE5\u56DE\u8F6C\u8EAB\u6765\u3002\u6709\u4EBA\u5413\u5F97\u5927\u53EB\u4E00\u58F0\uFF0C\u5B69\u5B50\u542C\u5230\u53EB\u58F0\u5F80\u4E0B\u4E00\u671B\uFF0C\u4E24\u6761\u817F\u4E0D\u7531\u5F97\u53D1\u8D77\u6296\u6765\u3002\u60C5\u51B5\u4E07\u5206\u5371\u6025\u3002",
        example: "\u811A\u4E0B\u7684\u6A2A\u6728\u53C8\u9AD8\u53C8\u7A84\uFF0C\u5B69\u5B50\u4E00\u4F4E\u5934\u770B\u89C1\u5927\u6D77\uFF0C\u817F\u90FD\u8F6F\u4E86\u3002",
        figure: { type: "scene", bg: "water", emojis: ["\u{1F640}", "\u{1F30A}", "\u{1F6A2}"], title: "\u7AD9\u5728\u9AD8\u9AD8\u7684\u6A2A\u6728\u4E0A", text: "\u6A2A\u6728\u53C8\u9AD8\u53C8\u7A84\uFF0C\u5B69\u5B50\u4E00\u5931\u8DB3\u5C31\u6CA1\u547D\u3002" },
        check: { q: "\u5B69\u5B50\u7AD9\u5728\u6A2A\u6728\u4E0A\u4E3A\u4EC0\u4E48\u7279\u522B\u5371\u9669\uFF1F", options: ["\u4E00\u5931\u8DB3\u6454\u4E0B\u5C31\u6CA1\u547D\uFF0C\u4E5F\u96BE\u56DE\u8F6C\u8EAB\u6765", "\u7334\u5B50\u4F1A\u6765\u54AC\u4ED6", "\u6A2A\u6728\u4F1A\u81EA\u5DF1\u65AD\u6389"], answer: 0 }
      },
      {
        title: "\u8239\u957F\u7684\u547D\u4EE4",
        text: "\u6B63\u5728\u8FD9\u65F6\uFF0C\u8239\u957F\u4ECE\u8239\u8231\u51FA\u6765\uFF0C\u624B\u91CC\u62FF\u7740\u4E00\u652F\u67AA\u3002\u770B\u89C1\u513F\u5B50\u5728\u6A2A\u6728\u4E0A\uFF0C\u4ED6\u7ACB\u523B\u7784\u51C6\u513F\u5B50\u558A\uFF1A\u201C\u5411\u6D77\u91CC\u8DF3\uFF01\u5FEB\uFF01\u4E0D\u8DF3\u6211\u5C31\u5F00\u67AA\u4E86\uFF01\u201D\u5B69\u5B50\u5413\u5F97\u6447\u6447\u6643\u6643\uFF0C\u6CA1\u542C\u660E\u767D\u3002\u8239\u957F\u53C8\u558A\uFF1A\u201C\u5411\u6D77\u91CC\u8DF3\uFF01\u4E0D\u7136\u6211\u5C31\u5F00\u67AA\u4E86\uFF01\u4E00\uFF01\u4E8C\uFF01\u201D\u521A\u558A\u51FA\u201C\u4E09\u201D\uFF0C\u5B69\u5B50\u7EB5\u8EAB\u4ECE\u6A2A\u6728\u4E0A\u8DF3\u4E0B\u6765\uFF0C\u6251\u901A\u4E00\u58F0\u50CF\u9897\u70AE\u5F39\u624E\u8FDB\u6D77\u91CC\u3002\u4E8C\u5341\u6765\u4E2A\u6C34\u624B\u65E9\u5DF2\u8DF3\u8FDB\u5927\u6D77\uFF0C\u7B49\u5B69\u5B50\u4E00\u6D6E\u4E0A\u6765\u5C31\u6293\u4F4F\u4ED6\uFF0C\u628A\u4ED6\u6551\u4E0A\u4E86\u7532\u677F\u3002\u5371\u6025\u5173\u5934\uFF0C\u8239\u957F\u6C89\u7740\u51B7\u9759\u3001\u5F53\u673A\u7ACB\u65AD\uFF0C\u7528\u547D\u4EE4\u6551\u4E86\u513F\u5B50\u3002",
        example: "\u201C\u4E00\uFF01\u4E8C\uFF01\u201D\u521A\u6570\u5230\u201C\u4E09\u201D\uFF0C\u5B69\u5B50\u6251\u901A\u4E00\u58F0\u8DF3\u8FDB\u5927\u6D77\u3002",
        figure: { type: "scene", bg: "water", emojis: ["\u{1F52B}", "\u{1F30A}", "\u{1F468}\u200D\u2708\uFE0F"], title: "\u8239\u957F\u547D\u4EE4\u8DF3\u6C34", text: "\u8239\u957F\u4E3E\u67AA\u6570\u7740\u201C\u4E00\u3001\u4E8C\u3001\u4E09\u201D\uFF0C\u903C\u5B69\u5B50\u8DF3\u6D77\u3002" },
        check: { q: "\u8239\u957F\u4E3A\u4EC0\u4E48\u903C\u7740\u5B69\u5B50\u5F80\u6D77\u91CC\u8DF3\uFF1F", options: ["\u8DF3\u6D77\u624D\u80FD\u8131\u79BB\u9669\u5883\uFF0C\u4FDD\u4F4F\u6027\u547D", "\u60F3\u5413\u552C\u4E00\u4E0B\u7334\u5B50", "\u8BA9\u5B69\u5B50\u7EC3\u4E60\u6E38\u6CF3"], answer: 0 }
      }
    ],
    rhyme: "\u7334\u5B50\u653E\u8086\u62A2\u5E3D\u5B50\uFF0C\u5B69\u5B50\u8FFD\u5E3D\u4E0A\u6845\u6746\uFF1B\n\u6A2A\u6728\u53C8\u9AD8\u53C8\u5371\u9669\uFF0C\u6C34\u624B\u4E2A\u4E2A\u5FC3\u53D1\u614C\uFF1B\n\u8239\u957F\u4E3E\u67AA\u559D\u8DF3\u6C34\uFF0C\u6C89\u7740\u679C\u65AD\u6551\u56DE\u513F\u3002",
    points: [
      "\u6545\u4E8B\u7684\u8D77\u56E0\uFF1A\u7334\u5B50\u6458\u4E0B\u5B69\u5B50\u7684\u5E3D\u5B50\u5E76\u722C\u4E0A\u6845\u6746\uFF0C\u5B69\u5B50\u53BB\u8FFD\u3002",
      "\u6545\u4E8B\u7684\u7ECF\u8FC7\uFF1A\u5B69\u5B50\u8FFD\u5230\u6700\u9AD8\u7684\u6A2A\u6728\u4E0A\uFF0C\u60C5\u51B5\u4E07\u5206\u5371\u6025\uFF0C\u6C34\u624B\u4EEC\u90FD\u5413\u5446\u4E86\u3002",
      "\u6545\u4E8B\u7684\u9AD8\u6F6E\u4E0E\u7ED3\u5C40\uFF1A\u8239\u957F\u7528\u67AA\u903C\u5B69\u5B50\u8DF3\u6C34\uFF0C\u6C34\u624B\u4EEC\u6551\u8D77\u4E86\u4ED6\u3002",
      "\u4EBA\u7269\u7279\u70B9\uFF1A\u8239\u957F\u5728\u5371\u6025\u5173\u5934\u6C89\u7740\u51B7\u9759\u3001\u5F53\u673A\u7ACB\u65AD\uFF1B\u5B69\u5B50\u52C7\u6562\u4F46\u51B2\u52A8\u3002"
    ],
    quiz: { q: "\u5B69\u5B50\u6700\u540E\u662F\u600E\u6837\u8131\u9669\u7684\uFF1F", options: ["\u542C\u4ECE\u8239\u957F\u7684\u547D\u4EE4\u8DF3\u8FDB\u6D77\u91CC\uFF0C\u88AB\u6C34\u624B\u6551\u8D77", "\u81EA\u5DF1\u6CBF\u7740\u6A2A\u6728\u8D70\u56DE\u6765", "\u7334\u5B50\u628A\u5E3D\u5B50\u8FD8\u7ED9\u4E86\u4ED6"], answer: 0 }
  },
  /* ------------------------------ 第七单元 ------------------------------ */
  "chinese-g5-b-7-1": {
    example: "\u5A01\u5C3C\u65AF\u662F\u4E16\u754C\u95FB\u540D\u7684\u6C34\u4E0A\u57CE\u5E02\uFF0C\u90A3\u91CC\u6CA1\u6709\u5BBD\u9614\u7684\u9A6C\u8DEF\uFF0C\u4E00\u6761\u6761\u6CB3\u9053\u5C31\u662F\u5927\u8857\uFF0C\u5C0F\u8247\u5C31\u662F\u5927\u8857\u4E0A\u7684\u201C\u6C7D\u8F66\u201D\u3002\u7F8E\u56FD\u4F5C\u5BB6\u9A6C\u514B\xB7\u5410\u6E29\u5E26\u6211\u4EEC\u5750\u4E0A\u5C0F\u8247\uFF0C\u53BB\u901B\u4E00\u901B\u8FD9\u5EA7\u795E\u5947\u7684\u6C34\u57CE\u3002",
    steps: [
      {
        title: "\u6C34\u4E0A\u7684\u201C\u5927\u8857\u201D",
        text: "\u5A01\u5C3C\u65AF\u662F\u6C34\u4E0A\u57CE\u5E02\uFF0C\u6CB3\u9053\u7EB5\u6A2A\u4EA4\u53C9\uFF0C\u5C0F\u8247\u6210\u4E86\u4E3B\u8981\u7684\u4EA4\u901A\u5DE5\u5177\uFF0C\u7B49\u4E8E\u5927\u8857\u4E0A\u7684\u6C7D\u8F66\u3002\u5546\u4EBA\u3001\u5987\u5973\u3001\u5B69\u5B50\u3001\u8001\u4EBA\u90FD\u8981\u9760\u5C0F\u8247\u51FA\u884C\uFF0C\u5B83\u5C31\u50CF\u8FD9\u5EA7\u57CE\u5E02\u7684\u201C\u817F\u201D\u3002\u8BFE\u6587\u4E00\u5F00\u5934\u5C31\u544A\u8BC9\u6211\u4EEC\uFF1A\u5C0F\u8247\u548C\u5A01\u5C3C\u65AF\u4EBA\u7684\u751F\u6D3B\u5206\u4E0D\u5F00\u3002",
        example: "\u4E00\u6761\u6761\u6CB3\u9053\u5C31\u662F\u8857\u9053\uFF0C\u5C0F\u8247\u561F\u561F\u5F00\u8FC7\uFF0C\u50CF\u6C7D\u8F66\u9A76\u8FC7\u5927\u8857\u3002",
        figure: { type: "scene", bg: "water", emojis: ["\u{1F6A3}", "\u{1F3D8}\uFE0F", "\u{1F30A}"], title: "\u6CB3\u9053\u5C31\u662F\u5927\u8857", text: "\u6CB3\u9053\u7EB5\u6A2A\u662F\u8857\u9053\uFF0C\u5C0F\u8247\u50CF\u5927\u8857\u4E0A\u7684\u6C7D\u8F66\u3002" },
        check: { q: "\u5728\u5A01\u5C3C\u65AF\uFF0C\u4E3B\u8981\u7684\u4EA4\u901A\u5DE5\u5177\u662F\u4EC0\u4E48\uFF1F", options: ["\u5C0F\u8247", "\u6C7D\u8F66", "\u98DE\u673A"], answer: 0 }
      },
      {
        title: "\u50CF\u65B0\u6708\u53C8\u50CF\u6C34\u86C7",
        text: "\u5A01\u5C3C\u65AF\u7684\u5C0F\u8247\u6709\u4E8C\u4E09\u5341\u82F1\u5C3A\u957F\uFF0C\u53C8\u7A84\u53C8\u6DF1\uFF0C\u6709\u70B9\u50CF\u72EC\u6728\u821F\u3002\u8239\u5934\u548C\u8239\u8244\u5411\u4E0A\u7FD8\u8D77\uFF0C\u50CF\u6302\u5728\u5929\u8FB9\u7684\u65B0\u6708\uFF1B\u884C\u52A8\u8D77\u6765\u8F7B\u5FEB\u7075\u6D3B\uFF0C\u4EFF\u4F5B\u7530\u6C9F\u91CC\u7684\u6C34\u86C7\u3002\u5750\u5728\u8239\u8231\u91CC\uFF0C\u76AE\u57AB\u5B50\u8F6F\u8F6F\u7684\u50CF\u6C99\u53D1\u4E00\u822C\uFF1B\u5C0F\u8247\u7A7F\u8FC7\u4E00\u5EA7\u5EA7\u5F62\u5F0F\u4E0D\u540C\u7684\u77F3\u6865\uFF0C\u6211\u4EEC\u6253\u5F00\u7A97\u5E18\uFF0C\u671B\u671B\u4E24\u5CB8\u7684\u53E4\u5EFA\u7B51\uFF0C\u8DDF\u6765\u5F80\u7684\u8239\u53EA\u6253\u62DB\u547C\uFF0C\u6709\u8BF4\u4E0D\u5B8C\u7684\u60C5\u8DA3\u3002",
        example: "\u4E24\u5934\u7FD8\u8D77\u7684\u5C0F\u8247\u5212\u8FC7\u6C34\u9762\uFF0C\u8F7B\u5FEB\u5F97\u50CF\u4E00\u6761\u7075\u6D3B\u7684\u6C34\u86C7\u3002",
        figure: { type: "scene", bg: "water", emojis: ["\u{1F319}", "\u{1F40D}", "\u{1F6A3}"], title: "\u65B0\u6708\u4E0E\u6C34\u86C7\u822C\u7684\u5C0F\u8247", text: "\u5C0F\u8247\u50CF\u5929\u8FB9\u65B0\u6708\uFF0C\u53C8\u8F7B\u5FEB\u5F97\u50CF\u7530\u6C9F\u6C34\u86C7\u3002" },
        check: { q: "\u8BFE\u6587\u628A\u5C0F\u8247\u6BD4\u4F5C\u4E86\u4EC0\u4E48\uFF1F", options: ["\u6302\u5728\u5929\u8FB9\u7684\u65B0\u6708\u3001\u7530\u6C9F\u91CC\u7684\u6C34\u86C7", "\u5927\u5361\u8F66\u548C\u706B\u8F66", "\u6D77\u4E0A\u7684\u8F6E\u8239"], answer: 0 }
      },
      {
        title: "\u8239\u592B\u4E0E\u5C0F\u8247\u7684\u4E00\u5929",
        text: "\u8239\u592B\u7684\u9A7E\u9A76\u6280\u672F\u7279\u522B\u597D\uFF1A\u884C\u8239\u901F\u5EA6\u6781\u5FEB\uFF0C\u6765\u5F80\u8239\u53EA\u5F88\u591A\uFF0C\u4ED6\u64CD\u7EB5\u81EA\u5982\uFF0C\u6BEB\u4E0D\u624B\u5FD9\u811A\u4E71\uFF1B\u4E0D\u7BA1\u591A\u62E5\u6324\uFF0C\u603B\u80FD\u5DE6\u62D0\u53F3\u62D0\u5730\u6324\u8FC7\u53BB\uFF1B\u9047\u5230\u6781\u7A84\u7684\u5730\u65B9\uFF0C\u4E5F\u80FD\u5E73\u7A33\u7A7F\u8FC7\u3001\u6025\u8F6C\u5F2F\u3002\u767D\u5929\uFF0C\u5546\u4EBA\u5939\u7740\u5927\u5305\u8D27\u7269\u5750\u5C0F\u8247\u53BB\u505A\u751F\u610F\uFF0C\u5987\u5973\u9AD8\u58F0\u8C08\u7B11\uFF0C\u5B69\u5B50\u4EEC\u5750\u5C0F\u8247\u5230\u90CA\u5916\u547C\u5438\u65B0\u9C9C\u7A7A\u6C14\uFF0C\u8001\u4EBA\u5750\u5C0F\u8247\u53BB\u6559\u5802\u7977\u544A\u3002\u534A\u591C\uFF0C\u620F\u9662\u6563\u573A\uFF0C\u4EBA\u4EEC\u6D8C\u4E0A\u5404\u81EA\u7684\u5C0F\u8247\uFF0C\u54D7\u7B11\u58F0\u6E10\u6E10\u8FDC\u53BB\uFF1B\u6C34\u9762\u6C89\u5BC2\u4E0B\u6765\uFF0C\u6708\u4EAE\u5F71\u5B50\u5728\u6C34\u4E2D\u6447\u6643\uFF0C\u53E4\u8001\u7684\u5A01\u5C3C\u65AF\u6C89\u6C89\u5730\u5165\u7761\u4E86\u3002\u767D\u5929\u70ED\u95F9\u3001\u591C\u665A\u5B81\u9759\uFF0C\u52A8\u9759\u7ED3\u5408\uFF0C\u5199\u6D3B\u4E86\u6C34\u57CE\u3002",
        example: "\u6DF1\u591C\uFF0C\u5C0F\u8247\u90FD\u505C\u6CCA\u5728\u7801\u5934\uFF0C\u5A01\u5C3C\u65AF\u5728\u6708\u5149\u4E0B\u9759\u9759\u5730\u7761\u7740\u4E86\u3002",
        figure: { type: "scene", bg: "water", emojis: ["\u{1F303}", "\u{1F319}", "\u{1F6A3}"], title: "\u5165\u68A6\u7684\u5A01\u5C3C\u65AF", text: "\u591C\u6DF1\u6C34\u9762\u6C89\u5BC2\u6708\u5F71\u6447\uFF0C\u6C34\u57CE\u6C89\u6C89\u5165\u7761\u3002" },
        check: { q: "\u8BFE\u6587\u7ED3\u5C3E\uFF0C\u591C\u665A\u7684\u5A01\u5C3C\u65AF\u662F\u4EC0\u4E48\u6837\u5B50\uFF1F", options: ["\u6C34\u9762\u6C89\u5BC2\uFF0C\u5A01\u5C3C\u65AF\u6C89\u6C89\u5165\u7761", "\u8857\u4E0A\u8F66\u6C34\u9A6C\u9F99", "\u5C0F\u8247\u8FD8\u5728\u98DE\u5954"], answer: 0 }
      }
    ],
    rhyme: "\u6C34\u4E0A\u57CE\u5E02\u5A01\u5C3C\u65AF\uFF0C\u7EB5\u6A2A\u6CB3\u9053\u662F\u5927\u8857\uFF1B\n\u5C0F\u8247\u7A84\u957F\u50CF\u65B0\u6708\uFF0C\u884C\u6765\u8F7B\u5FEB\u5982\u6C34\u86C7\uFF1B\n\u8239\u592B\u6280\u672F\u771F\u9AD8\u8D85\uFF0C\u663C\u95F9\u591C\u9759\u4E24\u76F8\u5B9C\u3002",
    points: [
      "\u5A01\u5C3C\u65AF\u662F\u6C34\u4E0A\u57CE\u5E02\uFF0C\u5C0F\u8247\u662F\u4E3B\u8981\u4EA4\u901A\u5DE5\u5177\uFF0C\u50CF\u5927\u8857\u4E0A\u7684\u6C7D\u8F66\u3002",
      "\u5C0F\u8247\u7684\u6837\u5B50\uFF1A\u53C8\u7A84\u53C8\u6DF1\uFF0C\u8239\u5934\u548C\u8239\u8244\u5411\u4E0A\u7FD8\uFF0C\u50CF\u65B0\u6708\u3001\u50CF\u6C34\u86C7\uFF1B\u5750\u8231\u91CC\u76AE\u57AB\u8F6F\u8F6F\u50CF\u6C99\u53D1\u3002",
      "\u8239\u592B\u9A7E\u9A76\u6280\u672F\u9AD8\u8D85\uFF1A\u64CD\u7EB5\u81EA\u5982\u3001\u5DE6\u62D0\u53F3\u62D0\u3001\u5E73\u7A33\u7A7F\u8FC7\u7A84\u5904\u3001\u80FD\u505A\u6025\u8F6C\u5F2F\u3002",
      "\u5C0F\u8247\u4E0E\u4EBA\u4EEC\u7684\u751F\u6D3B\u606F\u606F\u76F8\u5173\uFF1A\u767D\u5929\u5FD9\u788C\u70ED\u95F9\uFF0C\u6DF1\u591C\u620F\u9662\u6563\u573A\u540E\u6C34\u9762\u6C89\u5BC2\uFF0C\u5A01\u5C3C\u65AF\u6C89\u6C89\u5165\u7761\u3002"
    ],
    quiz: { q: "\u5C0F\u8247\u5728\u5A01\u5C3C\u65AF\u4EBA\u7684\u751F\u6D3B\u4E2D\u8D77\u4EC0\u4E48\u4F5C\u7528\uFF1F", options: ["\u662F\u4E3B\u8981\u7684\u4EA4\u901A\u5DE5\u5177\uFF0C\u50CF\u5927\u8857\u4E0A\u7684\u6C7D\u8F66", "\u53EA\u662F\u7528\u6765\u89C2\u5149\u73A9\u7684", "\u53EA\u6709\u5546\u4EBA\u624D\u80FD\u4E58\u5750"], answer: 0 }
  },
  "chinese-g5-b-7-2": {
    example: "\u6B27\u6D32\u6709\u4E00\u4E2A\u56FD\u5BB6\u53EB\u8377\u5170\uFF0C\u90A3\u91CC\u8FD0\u6CB3\u7EB5\u6A2A\uFF0C\u9C9C\u82B1\u904D\u5730\uFF0C\u53EF\u4F5C\u8005\u5374\u8BF4\u5B83\u201C\u662F\u7267\u573A\u4E4B\u56FD\u201D\u3002\u78A7\u7EFF\u7684\u8349\u539F\u4E0A\uFF0C\u82B1\u725B\u4F4E\u5934\u5403\u8349\uFF0C\u9A8F\u9A6C\u81EA\u7531\u5954\u9A70\u2026\u2026\u8BA9\u6211\u4EEC\u8DDF\u968F\u8BFE\u6587\uFF0C\u8D70\u8FDB\u8FD9\u5B81\u9759\u5B89\u8BE6\u7684\u7530\u56ED\u4E16\u754C\u3002",
    steps: [
      {
        title: "\u78A7\u7EFF\u8349\u539F\u4E0A\u7684\u725B\u7FA4",
        text: "\u8377\u5170\u662F\u6C34\u4E4B\u56FD\u3001\u82B1\u4E4B\u56FD\uFF0C\u4E5F\u662F\u7267\u573A\u4E4B\u56FD\u3002\u4E00\u6761\u6761\u8FD0\u6CB3\u4E4B\u95F4\u7684\u7EFF\u8272\u4F4E\u5730\u4E0A\uFF0C\u9ED1\u767D\u82B1\u725B\u3001\u767D\u5934\u9ED1\u725B\u3001\u767D\u8170\u84DD\u5634\u9ED1\u725B\u5728\u4F4E\u5934\u5403\u8349\uFF0C\u6709\u7684\u725B\u80CC\u4E0A\u76D6\u7740\u9632\u6F6E\u7684\u6BDB\u6BE1\u3002\u725B\u7FA4\u5403\u8349\u65F6\u975E\u5E38\u4E13\u6CE8\uFF0C\u6709\u65F6\u7AD9\u7ACB\u4E0D\u52A8\uFF0C\u4EFF\u4F5B\u6B63\u5728\u601D\u8003\u7740\u4EC0\u4E48\u3002\u725B\u728A\u7684\u6A21\u6837\u50CF\u8D35\u592B\u4EBA\uFF0C\u4EEA\u6001\u7AEF\u5E84\uFF1B\u8001\u725B\u597D\u4F3C\u725B\u7FA4\u7684\u5BB6\u957F\uFF0C\u65E0\u6BD4\u5C0A\u4E25\u3002\u6781\u76EE\u8FDC\u773A\uFF0C\u56DB\u5468\u5168\u662F\u4E1D\u7ED2\u822C\u7684\u78A7\u7EFF\u8349\u539F\u548C\u9ED1\u767D\u4E24\u8272\u7684\u82B1\u725B\u2014\u2014\u8FD9\u5C31\u662F\u771F\u6B63\u7684\u8377\u5170\u3002",
        example: "\u4E1D\u7ED2\u822C\u7684\u78A7\u7EFF\u8349\u539F\u4E0A\uFF0C\u9ED1\u767D\u82B1\u725B\u5B89\u5B89\u9759\u9759\u5730\u5403\u7740\u8349\u3002",
        figure: { type: "scene", bg: "field", emojis: ["\u{1F404}", "\u{1F33F}", "\u{1F337}"], title: "\u8349\u539F\u4E0A\u7684\u82B1\u725B", text: "\u4E1D\u7ED2\u822C\u7684\u78A7\u7EFF\u8349\u539F\uFF0C\u82B1\u725B\u5B89\u8BE6\u5730\u5403\u8349\u3002" },
        check: { q: "\u8BFE\u6587\u8BF4\u8377\u5170\u662F\u6C34\u4E4B\u56FD\u3001\u82B1\u4E4B\u56FD\uFF0C\u8FD8\u662F\u4EC0\u4E48\u4E4B\u56FD\uFF1F", options: ["\u7267\u573A\u4E4B\u56FD", "\u6C99\u6F20\u4E4B\u56FD", "\u96EA\u5C71\u4E4B\u56FD"], answer: 0 }
      },
      {
        title: "\u9A8F\u9A6C\u7684\u81EA\u7531\u738B\u56FD",
        text: "\u8FD9\u5C31\u662F\u771F\u6B63\u7684\u8377\u5170\uFF1A\u78A7\u7EFF\u8272\u7684\u4F4E\u5730\u9576\u5D4C\u5728\u4E00\u6761\u6761\u8FD0\u6CB3\u4E4B\u95F4\uFF0C\u6210\u7FA4\u7684\u9A8F\u9A6C\uFF0C\u5339\u5339\u8198\u80A5\u4F53\u58EE\u3002\u9664\u4E86\u6DF1\u6DF1\u7684\u91CE\u8349\u906E\u63A9\u7740\u7684\u8FD0\u6CB3\uFF0C\u6CA1\u6709\u4EC0\u4E48\u80FD\u591F\u963B\u6321\u5B83\u4EEC\u98DE\u9A70\u5230\u8FDC\u65B9\u3002\u8FBD\u9614\u65E0\u57A0\u7684\u539F\u91CE\u4F3C\u4E4E\u5F52\u5B83\u4EEC\u6240\u6709\uFF0C\u5B83\u4EEC\u662F\u8FD9\u4E2A\u81EA\u7531\u738B\u56FD\u7684\u4E3B\u4EBA\u548C\u516C\u7235\u3002\u4F5C\u8005\u7528\u201C\u4E3B\u4EBA\u201D\u201C\u516C\u7235\u201D\u6765\u5F62\u5BB9\u9A8F\u9A6C\uFF0C\u5199\u51FA\u4E86\u5B83\u4EEC\u7684\u81EA\u7531\u4E0E\u5C0A\u4E25\u3002",
        example: "\u8198\u80A5\u4F53\u58EE\u7684\u9A8F\u9A6C\u5728\u539F\u91CE\u4E0A\u5C3D\u60C5\u98DE\u9A70\uFF0C\u8C01\u4E5F\u6321\u4E0D\u4F4F\u5B83\u4EEC\u3002",
        figure: { type: "scene", bg: "field", emojis: ["\u{1F40E}", "\u{1F33E}", "\u{1F32C}\uFE0F"], title: "\u81EA\u7531\u5954\u8DD1\u7684\u9A8F\u9A6C", text: "\u8198\u80A5\u4F53\u58EE\u7684\u9A8F\u9A6C\uFF0C\u662F\u539F\u91CE\u81EA\u7531\u738B\u56FD\u4E3B\u4EBA\u3002" },
        check: { q: "\u5728\u7267\u573A\u4E4B\u56FD\uFF0C\u9A8F\u9A6C\u4EEC\u50CF\u4EC0\u4E48\uFF1F", options: ["\u81EA\u7531\u738B\u56FD\u7684\u4E3B\u4EBA\u548C\u516C\u7235", "\u88AB\u5173\u8D77\u6765\u7684\u56DA\u72AF", "\u8349\u539F\u4E0A\u7684\u5BA2\u4EBA"], answer: 0 }
      },
      {
        title: "\u4ECE\u508D\u665A\u5230\u6DF1\u591C\u7684\u5B81\u9759",
        text: "\u5230\u4E86\u508D\u665A\uFF0C\u624D\u6709\u4EBA\u9A7E\u7740\u5C0F\u8239\u6765\u7ED9\u5976\u725B\u6324\u5976\uFF1A\u91D1\u8272\u7684\u665A\u971E\u94FA\u5728\u897F\u5929\uFF0C\u6324\u5976\u7684\u4EBA\u9ED8\u9ED8\u65E0\u8A00\uFF0C\u8C01\u4E5F\u4E0D\u53EB\u558A\u5406\u559D\uFF0C\u725B\u8116\u5B50\u4E0A\u7684\u94C3\u94DB\u4E5F\u4E0D\u54CD\u3002\u8FD0\u6CB3\u91CC\u88C5\u6EE1\u5976\u6876\u7684\u8239\u7F13\u7F13\u884C\u9A76\uFF0C\u6EE1\u8F7D\u725B\u5976\u7684\u6C7D\u8F66\u3001\u706B\u8F66\u4E0D\u505C\u5F00\u5F80\u57CE\u5E02\u3002\u8F66\u8239\u8FC7\u540E\uFF0C\u4E00\u5207\u53C8\u6062\u590D\u4E86\u5E73\u9759\u3002\u5165\u591C\uFF0C\u72D7\u4E0D\u53EB\u4E86\uFF0C\u5708\u91CC\u7684\u725B\u4E0D\u518D\u54DE\u54DE\uFF0C\u9A6C\u4E5F\u5FD8\u4E86\u8E22\u6321\u677F\uFF1B\u6C89\u7761\u7684\u7272\u755C\u3001\u65E0\u58F0\u7684\u4F4E\u5730\u3001\u6F06\u9ED1\u7684\u591C\u665A\uFF0C\u53EA\u6709\u8FDC\u5904\u51E0\u5EA7\u706F\u5854\u95EA\u7740\u5FAE\u5F31\u7684\u5149\u3002\u8FD9\u5C31\u662F\u771F\u6B63\u7684\u8377\u5170\u2014\u2014\u5B81\u9759\u3001\u5B89\u8BE6\u7684\u7267\u573A\u4E4B\u56FD\u3002",
        example: "\u591C\u5E55\u964D\u4E34\uFF0C\u7272\u755C\u6C89\u6C89\u7761\u53BB\uFF0C\u53EA\u6709\u706F\u5854\u5728\u8FDC\u5904\u4E00\u660E\u4E00\u706D\u3002",
        figure: { type: "scene", bg: "field", emojis: ["\u{1F306}", "\u{1F30C}", "\u{1F69C}"], title: "\u4ECE\u9EC4\u660F\u5230\u6DF1\u591C", text: "\u665A\u971E\u91CC\u9759\u9759\u6324\u5976\uFF0C\u591C\u6DF1\u7272\u755C\u6C89\u7761\u706F\u5854\u660E\u3002" },
        check: { q: "\u591C\u665A\u7684\u8377\u5170\u7267\u573A\u662F\u600E\u6837\u7684\u666F\u8C61\uFF1F", options: ["\u7272\u755C\u6C89\u7761\uFF0C\u56DB\u5468\u4E00\u7247\u5B81\u9759", "\u725B\u9A6C\u8FD8\u5728\u72C2\u5954", "\u673A\u5668\u58F0\u9686\u9686\u54CD"], answer: 0 }
      }
    ],
    rhyme: "\u8377\u5170\u6709\u6C34\u53C8\u6709\u82B1\uFF0C\u8FD8\u662F\u8FBD\u9614\u7267\u573A\u56FD\uFF1B\n\u9ED1\u767D\u82B1\u725B\u4E13\u6CE8\u5403\u8349\uFF0C\u9A8F\u9A6C\u5954\u9A70\u81EA\u81EA\u7531\u7531\uFF1B\n\u665A\u971E\u6324\u5976\u9759\u6084\u6084\uFF0C\u591C\u6765\u4E07\u7269\u5165\u68A6\u4E61\u3002",
    points: [
      "\u8377\u5170\u662F\u6C34\u4E4B\u56FD\u3001\u82B1\u4E4B\u56FD\uFF0C\u4E5F\u662F\u7267\u573A\u4E4B\u56FD\u3002",
      "\u767D\u5929\uFF1A\u78A7\u7EFF\u8349\u539F\u4E0A\u82B1\u725B\u5403\u8349\uFF0C\u725B\u728A\u50CF\u8D35\u592B\u4EBA\uFF0C\u8001\u725B\u50CF\u5BB6\u957F\uFF1B\u9A8F\u9A6C\u8198\u80A5\u4F53\u58EE\uFF0C\u662F\u81EA\u7531\u738B\u56FD\u7684\u4E3B\u4EBA\u3002",
      "\u508D\u665A\uFF1A\u4EBA\u4EEC\u9ED8\u9ED8\u6324\u5976\uFF0C\u88C5\u6EE1\u725B\u5976\u7684\u8F66\u8239\u8FD0\u5F80\u57CE\u5E02\uFF0C\u4E00\u5207\u5B89\u9759\u3002",
      "\u6DF1\u591C\uFF1A\u7272\u755C\u6C89\u7761\u3001\u4F4E\u5730\u65E0\u58F0\u3001\u706F\u5854\u95EA\u5149\uFF0C\u6574\u7BC7\u5F25\u6F2B\u7740\u5B81\u9759\u5B89\u8BE6\u7684\u6C14\u606F\uFF1B\u201C\u8FD9\u5C31\u662F\u771F\u6B63\u7684\u8377\u5170\u201D\u53CD\u590D\u51FA\u73B0\uFF0C\u662F\u5168\u6587\u7684\u4E2D\u5FC3\u53E5\u3002"
    ],
    quiz: { q: "\u4E3A\u4EC0\u4E48\u8BF4\u8377\u5170\u662F\u201C\u771F\u6B63\u7684\u7267\u573A\u4E4B\u56FD\u201D\uFF1F", options: ["\u90A3\u91CC\u6709\u8FBD\u9614\u7684\u7267\u573A\u3001\u6210\u7FA4\u7684\u7272\u755C\uFF0C\u5B81\u9759\u5B89\u8BE6", "\u90A3\u91CC\u53EA\u6709\u7267\u573A\u6CA1\u6709\u522B\u7684", "\u90A3\u91CC\u7684\u4EBA\u90FD\u4E0D\u5DE5\u4F5C"], answer: 0 }
  },
  "chinese-g5-b-7-3": {
    example: "\u5728\u975E\u6D32\u7684\u5C3C\u7F57\u6CB3\u7554\uFF0C\u77D7\u7ACB\u7740\u4E00\u5EA7\u5EA7\u5DE8\u5927\u7684\u91D1\u5B57\u5854\u3002\u5B83\u4EEC\u5728\u5915\u9633\u4E0B\u95EA\u7740\u91D1\u5149\uFF0C\u5DF2\u7ECF\u9ED8\u9ED8\u7AD9\u7ACB\u4E86\u56DB\u4E94\u5343\u5E74\u3002\u8FD9\u4E00\u8BFE\u6709\u4E24\u7BC7\u6587\u7AE0\uFF1A\u4E00\u7BC7\u662F\u4F18\u7F8E\u7684\u6563\u6587\u300A\u91D1\u5B57\u5854\u5915\u7167\u300B\uFF0C\u4E00\u7BC7\u662F\u4ECB\u7ECD\u77E5\u8BC6\u7684\u300A\u4E0D\u53EF\u601D\u8BAE\u7684\u91D1\u5B57\u5854\u300B\u3002",
    steps: [
      {
        title: "\u5915\u7167\u4E0B\u7684\u91D1\u5C71",
        text: "\u300A\u91D1\u5B57\u5854\u5915\u7167\u300B\u5199\u7684\u662F\u508D\u665A\u7684\u91D1\u5B57\u5854\uFF1A\u91D1\u8272\u7684\u5915\u9633\u4E0B\uFF0C\u91D1\u8272\u7684\u7530\u91CE\u3001\u91D1\u8272\u7684\u6C99\u6F20\uFF0C\u8FDE\u5C3C\u7F57\u6CB3\u7684\u6CB3\u6C34\u4E5F\u6CDB\u7740\u91D1\u5149\uFF0C\u53E4\u8001\u7684\u91D1\u5B57\u5854\u7B80\u76F4\u50CF\u7528\u7EAF\u91D1\u94F8\u6210\u7684\uFF0C\u8FDC\u8FDC\u671B\u53BB\u50CF\u4E00\u5EA7\u5EA7\u91D1\u5C71\u3002\u5B83\u6BD4\u6211\u4EEC\u7684\u6CF0\u5C71\u8FD8\u9AD8\uFF0C\u8D70\u8FD1\u4E86\u624D\u53D1\u73B0\uFF0C\u5B83\u662F\u90A3\u6837\u5DE8\u5927\u3001\u90A3\u6837\u5E84\u4E25\u3002\u6587\u7AE0\u7528\u4E00\u8FDE\u4E32\u201C\u91D1\u8272\u201D\uFF0C\u5199\u51FA\u91D1\u5B57\u5854\u5728\u5915\u7167\u4E2D\u7684\u58EE\u7F8E\u3002",
        example: "\u5915\u9633\u628A\u4E00\u5207\u90FD\u67D3\u6210\u91D1\u8272\uFF0C\u91D1\u5B57\u5854\u50CF\u4E00\u5EA7\u5EA7\u7528\u7EAF\u91D1\u94F8\u6210\u7684\u5927\u5C71\u3002",
        figure: { type: "scene", bg: "desert", emojis: ["\u{1F305}", "\u{1F53A}", "\u{1F3DC}\uFE0F"], title: "\u5915\u9633\u4E0B\u7684\u91D1\u5B57\u5854", text: "\u91D1\u8272\u5915\u7167\u91CC\uFF0C\u91D1\u5B57\u5854\u50CF\u4E00\u5EA7\u5EA7\u91D1\u5C71\u3002" },
        check: { q: "\u5915\u7167\u4E0B\u7684\u91D1\u5B57\u5854\uFF0C\u8FDC\u8FDC\u671B\u53BB\u50CF\u4EC0\u4E48\uFF1F", options: ["\u4E00\u5EA7\u5EA7\u91D1\u5C71", "\u4E00\u7247\u7247\u767D\u4E91", "\u4E00\u6392\u6392\u7EFF\u6811"], answer: 0 }
      },
      {
        title: "\u4E0D\u53EF\u601D\u8BAE\u7684\u6570\u5B57",
        text: "\u300A\u4E0D\u53EF\u601D\u8BAE\u7684\u91D1\u5B57\u5854\u300B\u544A\u8BC9\u6211\u4EEC\uFF1A\u91D1\u5B57\u5854\u662F\u53E4\u57C3\u53CA\u6CD5\u8001\u7684\u9675\u5893\uFF0C\u5EFA\u4E8E\u56DB\u4E94\u5343\u5E74\u524D\u3002\u5176\u4E2D\u6700\u5927\u7684\u80E1\u592B\u91D1\u5B57\u5854\uFF0C\u9AD8\u7EA6\u4E00\u767E\u56DB\u5341\u516D\u7C73\uFF0C\u76F8\u5F53\u4E8E\u51E0\u5341\u5C42\u697C\u90A3\u4E48\u9AD8\uFF1B\u5B83\u7528\u4E86\u7EA6\u4E8C\u767E\u4E09\u5341\u4E07\u5757\u77F3\u5934\uFF0C\u6BCF\u5757\u77F3\u5934\u91CD\u8FBE\u51E0\u5428\u3002\u8FD9\u4E48\u591A\u5DE8\u77F3\uFF0C\u662F\u600E\u4E48\u8FD0\u6765\u3001\u53C8\u662F\u600E\u4E48\u780C\u4E0A\u53BB\u7684\uFF0C\u81F3\u4ECA\u4ECD\u662F\u4E00\u4E2A\u8C1C\u3002",
        example: "\u80E1\u592B\u91D1\u5B57\u5854\u7528\u4E86\u7EA6\u4E8C\u767E\u4E09\u5341\u4E07\u5757\u77F3\u5934\uFF0C\u6BCF\u5757\u90FD\u6709\u597D\u51E0\u5428\u91CD\u3002",
        figure: { type: "scene", bg: "desert", emojis: ["\u{1FAA8}", "\u{1F4D0}", "\u{1F3DB}\uFE0F"], title: "\u5DE8\u77F3\u5792\u6210\u7684\u80E1\u592B\u91D1\u5B57\u5854", text: "\u80E1\u592B\u91D1\u5B57\u5854\u9AD8\u767E\u4F59\u7C73\uFF0C\u5DE8\u77F3\u4E8C\u767E\u4E09\u5341\u4E07\u5757\u3002" },
        check: { q: "\u6700\u5927\u7684\u80E1\u592B\u91D1\u5B57\u5854\u5927\u7EA6\u6709\u591A\u9AD8\uFF1F", options: ["\u9AD8\u7EA6\u4E00\u767E\u56DB\u5341\u516D\u7C73", "\u9AD8\u7EA6\u5341\u7C73", "\u548C\u666E\u901A\u697C\u623F\u4E00\u6837\u9AD8"], answer: 0 }
      },
      {
        title: "\u53E4\u57C3\u53CA\u4EBA\u7684\u667A\u6167",
        text: "\u91D1\u5B57\u5854\u7684\u5854\u8EAB\u7531\u4E00\u5757\u5757\u5DE8\u77F3\u5792\u6210\uFF0C\u77F3\u5757\u4E4B\u95F4\u4E25\u4E1D\u5408\u7F1D\uFF0C\u8FDE\u5200\u7247\u90FD\u63D2\u4E0D\u8FDB\u53BB\u3002\u5728\u6CA1\u6709\u8D77\u91CD\u673A\u3001\u6CA1\u6709\u673A\u5668\u7684\u56DB\u5343\u591A\u5E74\u524D\uFF0C\u53E4\u57C3\u53CA\u4EBA\u7ADF\u80FD\u628A\u51E0\u5428\u91CD\u7684\u5DE8\u77F3\u642C\u8FD0\u3001\u5806\u780C\u5F97\u5982\u6B64\u6574\u9F50\u7CBE\u5BC6\uFF0C\u8FD8\u8981\u8BA9\u5854\u8EAB\u4FDD\u6301\u7EDD\u5999\u7684\u65B9\u4F4D\uFF0C\u8FD9\u4E0D\u80FD\u4E0D\u4EE4\u4EBA\u60CA\u53F9\u3002\u91D1\u5B57\u5854\u81F3\u4ECA\u4ECD\u77D7\u7ACB\u5728\u5C3C\u7F57\u6CB3\u7554\uFF0C\u662F\u53E4\u57C3\u53CA\u6587\u660E\u4E0E\u667A\u6167\u7684\u8C61\u5F81\u3002",
        example: "\u4E24\u5757\u5DE8\u77F3\u4E25\u4E1D\u5408\u7F1D\uFF0C\u8FDE\u4E00\u7247\u8584\u8584\u7684\u5200\u7247\u90FD\u63D2\u4E0D\u8FDB\u53BB\u3002",
        figure: { type: "scene", bg: "desert", emojis: ["\u{1F53A}", "\u{1F9E0}", "\u{1F30D}"], title: "\u4EE4\u4EBA\u60CA\u53F9\u7684\u667A\u6167", text: "\u5DE8\u77F3\u4E25\u4E1D\u5408\u7F1D\u5200\u7247\u96BE\u5165\uFF0C\u5C3D\u663E\u53E4\u4EBA\u667A\u6167\u3002" },
        check: { q: "\u91D1\u5B57\u5854\u7684\u77F3\u5757\u780C\u5F97\u6709\u591A\u5BC6\uFF1F", options: ["\u4E25\u4E1D\u5408\u7F1D\uFF0C\u8FDE\u5200\u7247\u90FD\u63D2\u4E0D\u8FDB", "\u7F1D\u9699\u5927\u5F97\u80FD\u4F38\u8FDB\u62F3\u5934", "\u7528\u6CE5\u5DF4\u968F\u4FBF\u7CCA\u4E0A"], answer: 0 }
      }
    ],
    rhyme: "\u5915\u9633\u6D12\u91D1\u91D1\u5B57\u5854\uFF0C\u5DE8\u5927\u5E84\u4E25\u50CF\u91D1\u5C71\uFF1B\n\u80E1\u592B\u767E\u56DB\u5341\u516D\u7C73\uFF0C\u4E8C\u767E\u4E09\u5341\u4E07\u5757\u77F3\uFF1B\n\u77F3\u7F1D\u7D27\u5F97\u5200\u96BE\u5165\uFF0C\u53E4\u56FD\u667A\u6167\u6C38\u6D41\u4F20\u3002",
    points: [
      "\u300A\u91D1\u5B57\u5854\u5915\u7167\u300B\uFF1A\u7528\u201C\u91D1\u8272\u201D\u7684\u53CD\u590D\u63CF\u5199\uFF0C\u5199\u51FA\u91D1\u5B57\u5854\u5728\u5915\u7167\u4E2D\u50CF\u91D1\u5C71\u4E00\u6837\u58EE\u7F8E\u3002",
      "\u300A\u4E0D\u53EF\u601D\u8BAE\u7684\u91D1\u5B57\u5854\u300B\uFF1A\u91D1\u5B57\u5854\u662F\u53E4\u57C3\u53CA\u6CD5\u8001\u7684\u9675\u5893\uFF0C\u5EFA\u4E8E\u56DB\u4E94\u5343\u5E74\u524D\u3002",
      "\u80E1\u592B\u91D1\u5B57\u5854\u9AD8\u7EA6\u4E00\u767E\u56DB\u5341\u516D\u7C73\uFF0C\u7528\u7EA6\u4E8C\u767E\u4E09\u5341\u4E07\u5757\u5DE8\u77F3\u780C\u6210\uFF0C\u77F3\u5757\u4E4B\u95F4\u4E25\u4E1D\u5408\u7F1D\u3002",
      "\u5DE8\u77F3\u5982\u4F55\u642C\u8FD0\u3001\u780C\u8D77\u81F3\u4ECA\u662F\u8C1C\uFF0C\u91D1\u5B57\u5854\u662F\u53E4\u57C3\u53CA\u6587\u660E\u4E0E\u667A\u6167\u7684\u8C61\u5F81\u3002"
    ],
    quiz: { q: "\u91D1\u5B57\u5854\u662F\u4EC0\u4E48\u4EBA\u7684\u9675\u5893\uFF1F", options: ["\u53E4\u57C3\u53CA\u7684\u6CD5\u8001", "\u53E4\u4EE3\u4E2D\u56FD\u7684\u7687\u5E1D", "\u53E4\u5E0C\u814A\u7684\u54F2\u5B66\u5BB6"], answer: 0 }
  },
  /* ------------------------------ 第八单元 ------------------------------ */
  "chinese-g5-b-8-1": {
    example: "\u6881\u56FD\u6709\u4E00\u6237\u59D3\u6768\u7684\u4EBA\u5BB6\uFF0C\u5BB6\u91CC\u6709\u4E2A\u4E5D\u5C81\u7684\u5B69\u5B50\uFF0C\u975E\u5E38\u806A\u660E\u3002\u4E00\u5929\uFF0C\u4E00\u4F4D\u59D3\u5B54\u7684\u5BA2\u4EBA\u6765\u62DC\u8BBF\uFF0C\u6307\u7740\u6768\u6885\u5BF9\u5B69\u5B50\u8BF4\u201C\u8FD9\u662F\u4F60\u5BB6\u7684\u679C\u5B50\u201D\u3002\u5B69\u5B50\u5E94\u58F0\u56DE\u7B54\u4E86\u4E00\u53E5\u5999\u8BED\uFF0C\u628A\u5BA2\u4EBA\u90FD\u9017\u670D\u4E86\u3002\u6211\u4EEC\u8BFB\u4E00\u8BFB\u6587\u8A00\u6587\u300A\u6768\u6C0F\u4E4B\u5B50\u300B\u3002",
    steps: [
      {
        title: "\u4E5D\u5C81\u7684\u806A\u6167\u5C0F\u513F",
        text: "\u6881\u56FD\u6768\u6C0F\u5B50\u4E5D\u5C81\uFF0C\u751A\u806A\u60E0\u2014\u2014\u6881\u56FD\u6768\u5BB6\u7684\u5B69\u5B50\u4E5D\u5C81\uFF0C\u975E\u5E38\u806A\u660E\u3002\u5B54\u541B\u5E73\u6765\u62DC\u8BBF\u4ED6\u7684\u7236\u4EB2\uFF0C\u7236\u4EB2\u4E0D\u5728\u5BB6\uFF0C\u4FBF\u53EB\u5B69\u5B50\u51FA\u6765\u63A5\u5F85\u3002\u5B69\u5B50\u4E3A\u5BA2\u4EBA\u7AEF\u4E0A\u6C34\u679C\uFF0C\u679C\u76D8\u91CC\u5C31\u6709\u6768\u6885\u3002\u5C0F\u5C0F\u5E74\u7EAA\u5C31\u80FD\u793C\u8C8C\u5F85\u5BA2\uFF0C\u679C\u7136\u673A\u7075\u3002",
        example: "\u5BA2\u4EBA\u6765\u4E86\uFF0C\u4E5D\u5C81\u7684\u5B69\u5B50\u7AEF\u51FA\u6C34\u679C\u62DB\u5F85\uFF0C\u679C\u76D8\u91CC\u6446\u7740\u65B0\u9C9C\u7684\u6768\u6885\u3002",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F466}", "\u{1F352}", "\u{1F3EE}"], title: "\u7AEF\u679C\u5F85\u5BA2\u7684\u5C0F\u513F", text: "\u4E5D\u5C81\u5C0F\u513F\u5BB6\u4E2D\u7AEF\u679C\uFF0C\u793C\u8C8C\u8FCE\u63A5\u5B54\u541B\u5E73\u3002" },
        check: { q: "\u6768\u6C0F\u4E4B\u5B50\u89C1\u5230\u5BA2\u4EBA\u6765\uFF0C\u505A\u4E86\u4EC0\u4E48\uFF1F", options: ["\u4E3A\u5BA2\u4EBA\u7AEF\u4E0A\u6C34\u679C", "\u8EB2\u8D77\u6765\u4E0D\u89C1\u4EBA", "\u4E00\u53E5\u8BDD\u4E5F\u4E0D\u8BF4"], answer: 0 }
      },
      {
        title: "\u201C\u6B64\u662F\u541B\u5BB6\u679C\u201D",
        text: "\u5B54\u541B\u5E73\u6307\u7740\u6768\u6885\u5BF9\u5B69\u5B50\u8BF4\uFF1A\u201C\u6B64\u662F\u541B\u5BB6\u679C\u3002\u201D\u2014\u2014\u8FD9\u662F\u4F60\u4EEC\u6768\u5BB6\u7684\u679C\u5B50\u3002\u4ED6\u8FD9\u662F\u5728\u9017\u5B69\u5B50\u5462\uFF1A\u4F60\u59D3\u6768\uFF0C\u6768\u6885\u4E5F\u5E26\u4E2A\u201C\u6768\u201D\u5B57\uFF0C\u6240\u4EE5\u6768\u6885\u7B97\u662F\u4F60\u5BB6\u7684\u679C\u5B50\u3002\u8FD9\u8BDD\u8868\u9762\u4E0A\u5BA2\u6C14\uFF0C\u6697\u5730\u91CC\u5374\u8003\u5B69\u5B50\u80FD\u4E0D\u80FD\u542C\u51FA\u8BDD\u91CC\u7684\u673A\u950B\u3002",
        example: "\u5B54\u541B\u5E73\u6307\u7740\u6768\u6885\u7B11\u5475\u5475\u5730\u8BF4\uFF1A\u201C\u8FD9\u6768\u6885\uFF0C\u53EF\u662F\u4F60\u4EEC\u5BB6\u7684\u679C\u5B50\u5440\u3002\u201D",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F642}", "\u{1F449}", "\u{1F352}"], title: "\u5B54\u541B\u5E73\u9017\u5C0F\u513F", text: "\u5B54\u541B\u5E73\u6307\u7740\u6768\u6885\u6253\u8DA3\uFF1A\u6B64\u662F\u541B\u5BB6\u679C\u3002" },
        check: { q: "\u5B54\u541B\u5E73\u8BF4\u6768\u6885\u662F\u201C\u541B\u5BB6\u679C\u201D\uFF0C\u662F\u62FF\u4EC0\u4E48\u5F00\u73A9\u7B11\uFF1F", options: ["\u5B69\u5B50\u59D3\u6768\uFF0C\u6768\u6885\u4E5F\u6709\u4E2A\u201C\u6768\u201D\u5B57", "\u6768\u6885\u662F\u6768\u5BB6\u79CD\u7684", "\u6768\u6885\u6700\u597D\u5403"], answer: 0 }
      },
      {
        title: "\u201C\u672A\u95FB\u5B54\u96C0\u662F\u592B\u5B50\u5BB6\u79BD\u201D",
        text: "\u5B69\u5B50\u5E94\u58F0\u56DE\u7B54\uFF1A\u201C\u672A\u95FB\u5B54\u96C0\u662F\u592B\u5B50\u5BB6\u79BD\u3002\u201D\u2014\u2014\u6211\u53EF\u6CA1\u542C\u8BF4\u8FC7\u5B54\u96C0\u662F\u60A8\u5BB6\u7684\u9E1F\u5440\u3002\u5B54\u541B\u5E73\u59D3\u5B54\uFF0C\u5B54\u96C0\u4E5F\u6709\u4E2A\u201C\u5B54\u201D\u5B57\uFF0C\u5B69\u5B50\u5C31\u7167\u7740\u4ED6\u7684\u6CD5\u5B50\u56DE\u656C\uFF1A\u5982\u679C\u59D3\u6768\u7684\u4EBA\u5BB6\u80FD\u6709\u6768\u6885\uFF0C\u90A3\u59D3\u5B54\u7684\u4EBA\u5BB6\u5C82\u4E0D\u662F\u8BE5\u6709\u5B54\u96C0\uFF1F\u4E00\u4E2A\u201C\u672A\u95FB\u201D\uFF0C\u8BF4\u5F97\u59D4\u5A49\u53C8\u6709\u793C\u8C8C\uFF0C\u65E2\u6CA1\u6709\u9876\u649E\u5BA2\u4EBA\uFF0C\u53C8\u673A\u667A\u5730\u53CD\u9A73\u4E86\u4ED6\u3002\u8FD9\u5C31\u662F\u201C\u751A\u806A\u60E0\u201D\u7684\u4F53\u73B0\u3002",
        example: "\u201C\u6211\u53EF\u6CA1\u542C\u8BF4\u8FC7\uFF0C\u5B54\u96C0\u662F\u60A8\u5B54\u5BB6\u7684\u9E1F\u5462\uFF01\u201D\u5B69\u5B50\u5E94\u58F0\u800C\u7B54\u3002",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F99A}", "\u{1F466}", "\u{1F4A1}"], title: "\u5E94\u58F0\u5DE7\u7B54\u7684\u5C0F\u513F", text: "\u201C\u672A\u95FB\u5B54\u96C0\u662F\u592B\u5B50\u5BB6\u79BD\u201D\uFF0C\u673A\u667A\u53C8\u6709\u793C\u8C8C\u3002" },
        check: { q: "\u5B69\u5B50\u7528\u4EC0\u4E48\u8BDD\u6765\u5DE7\u5999\u56DE\u5E94\u5BA2\u4EBA\uFF1F", options: ["\u672A\u95FB\u5B54\u96C0\u662F\u592B\u5B50\u5BB6\u79BD", "\u6768\u6885\u4E0D\u662F\u6211\u5BB6\u7684", "\u60A8\u8BF4\u5F97\u4E0D\u5BF9"], answer: 0 }
      }
    ],
    rhyme: "\u6768\u5BB6\u5C0F\u513F\u4E5D\u5C81\u806A\uFF0C\u7AEF\u679C\u5F85\u5BA2\u6709\u793C\u8C8C\uFF1B\n\u5B54\u6307\u6768\u6885\u79F0\u541B\u679C\uFF0C\u8003\u4ED6\u80FD\u4E0D\u80FD\u542C\u5DE7\uFF1B\n\u201C\u672A\u95FB\u5B54\u96C0\u662F\u541B\u79BD\u201D\uFF0C\u5E94\u58F0\u5999\u7B54\u663E\u667A\u6167\u3002",
    points: [
      "\u5B57\u8BCD\u7406\u89E3\uFF1A\u751A\uFF08\u5F88\uFF09\u3001\u60E0\uFF08\u540C\u201C\u6167\u201D\uFF0C\u806A\u660E\uFF09\u3001\u8BE3\uFF08\u62DC\u8BBF\uFF09\u3001\u4E43\uFF08\u4E8E\u662F\uFF09\u3001\u592B\u5B50\uFF08\u5BF9\u7537\u5B50\u7684\u656C\u79F0\uFF09\u3002",
      "\u5B54\u541B\u5E73\u62FF\u201C\u6768\u6885\u201D\u7684\u201C\u6768\u201D\u548C\u5B69\u5B50\u7684\u59D3\u5F00\u73A9\u7B11\uFF0C\u8BF4\u6768\u6885\u662F\u201C\u541B\u5BB6\u679C\u201D\u3002",
      "\u5B69\u5B50\u5E94\u58F0\u56DE\u7B54\u201C\u672A\u95FB\u5B54\u96C0\u662F\u592B\u5B50\u5BB6\u79BD\u201D\uFF0C\u7528\u201C\u5B54\u96C0\u201D\u5BF9\u201C\u5B54\u201D\u59D3\uFF0C\u5DE7\u5999\u56DE\u656C\u3002",
      "\u4E00\u4E2A\u201C\u672A\u95FB\u201D\uFF0C\u65E2\u4E0D\u5931\u793C\u53C8\u673A\u667A\uFF0C\u8868\u73B0\u51FA\u6768\u6C0F\u4E4B\u5B50\u7684\u806A\u6167\u4E0E\u8BED\u8A00\u827A\u672F\u3002"
    ],
    quiz: { q: "\u6768\u6C0F\u4E4B\u5B50\u7684\u56DE\u7B54\u5999\u5728\u54EA\u91CC\uFF1F", options: ["\u987A\u7740\u5BA2\u4EBA\u7684\u73A9\u7B11\u5DE7\u5999\u53CD\u9A73\uFF0C\u53C8\u4E0D\u5931\u793C\u8C8C", "\u58F0\u97F3\u7279\u522B\u6D2A\u4EAE", "\u4ED6\u7ED9\u5BA2\u4EBA\u8BB2\u4E86\u4E2A\u6545\u4E8B"], answer: 0 }
  },
  "chinese-g5-b-8-2": {
    example: "\u6211\u4EEC\u6BCF\u4E2A\u4EBA\u90FD\u968F\u8EAB\u5E26\u7740\u5341\u6839\u624B\u6307\uFF0C\u5B83\u4EEC\u548C\u6211\u4EEC\u5F62\u5F71\u4E0D\u79BB\u3002\u53EF\u662F\u4F60\u8BA4\u771F\u770B\u8FC7\u5B83\u4EEC\u5417\uFF1F\u4E30\u5B50\u607A\u5148\u751F\u628A\u4E94\u6839\u624B\u6307\u5F53\u4F5C\u4E94\u79CD\u4EBA\u6765\u5199\uFF1A\u6709\u7684\u5403\u82E6\uFF0C\u6709\u7684\u673A\u654F\uFF0C\u6709\u7684\u517B\u5C0A\u5904\u4F18\u2026\u2026\u8BFB\u4E00\u8BFB\u300A\u624B\u6307\u300B\uFF0C\u770B\u770B\u4E94\u6307\u5404\u6709\u600E\u6837\u7684\u6027\u683C\u3002",
    steps: [
      {
        title: "\u4E94\u6307\u5404\u6709\u6240\u957F\u5404\u6709\u6240\u77ED",
        text: "\u8BFE\u6587\u5F00\u95E8\u89C1\u5C71\uFF1A\u4E00\u53EA\u624B\u4E0A\u7684\u4E94\u6839\u624B\u6307\uFF0C\u5404\u6709\u4E0D\u540C\u7684\u59FF\u6001\uFF0C\u5404\u5177\u4E0D\u540C\u7684\u6027\u683C\uFF0C\u5404\u6709\u6240\u957F\uFF0C\u5404\u6709\u6240\u77ED\u3002\u6709\u7684\u6837\u5B50\u597D\u770B\uFF0C\u6709\u7684\u4E0D\u597D\u770B\uFF1B\u6709\u7684\u51FA\u529B\u591A\uFF0C\u6709\u7684\u51FA\u529B\u5C11\u3002\u4E30\u5B50\u607A\u5148\u751F\u7528\u62DF\u4EBA\u7684\u624B\u6CD5\uFF0C\u628A\u624B\u6307\u5F53\u6210\u6709\u6027\u683C\u7684\u4EBA\u6765\u5199\uFF0C\u8BFB\u8D77\u6765\u683C\u5916\u6709\u8DA3\u3002",
        example: "\u4E94\u6839\u624B\u6307\u51D1\u5728\u4E00\u8D77\uFF0C\u50CF\u4E94\u4E2A\u6027\u683C\u5404\u4E0D\u76F8\u540C\u7684\u5C0F\u4F19\u4F34\u3002",
        figure: { type: "scene", bg: "indoor", emojis: ["\u270B", "\u{1F9D1}\u200D\u{1F91D}\u200D\u{1F9D1}", "\u{1F3AD}"], title: "\u4E94\u6307\u5982\u4E94\u4EBA", text: "\u4E94\u6307\u5404\u6709\u59FF\u6001\u6027\u683C\uFF0C\u50CF\u4E94\u4E2A\u4E0D\u540C\u7684\u4EBA\u3002" },
        check: { q: "\u8BFE\u6587\u8BA4\u4E3A\u4E94\u6839\u624B\u6307\u7684\u5173\u7CFB\u662F\u600E\u6837\u7684\uFF1F", options: ["\u5404\u6709\u6240\u957F\uFF0C\u5404\u6709\u6240\u77ED", "\u5927\u62C7\u6307\u6700\u6CA1\u7528", "\u4E94\u6839\u90FD\u4E00\u6837"], answer: 0 }
      },
      {
        title: "\u5403\u82E6\u7684\u5927\u62C7\u6307\u4E0E\u673A\u654F\u7684\u98DF\u6307",
        text: "\u5927\u62C7\u6307\u5F62\u72B6\u7B97\u4E0D\u4E0A\u7F8E\uFF1A\u8EAB\u4F53\u77EE\u800C\u80D6\uFF0C\u5934\u5927\u800C\u80A5\uFF0C\u53EA\u6709\u4E00\u4E2A\u5173\u8282\u3002\u4F46\u5728\u4E94\u6307\u4E2D\u5B83\u6700\u80AF\u5403\u82E6\uFF1A\u62C9\u80E1\u7434\u8981\u5B83\u6276\u4F4F\u7434\u8EAB\uFF0C\u6C34\u8981\u55B7\u51FA\u6765\u53EB\u5B83\u6B7B\u529B\u62B5\u4F4F\uFF0C\u8840\u8981\u6D41\u51FA\u6765\u53EB\u5B83\u62FC\u547D\u6309\u4F4F\uFF0C\u91CD\u4E1C\u897F\u7FFB\u5012\u53EB\u5B83\u4F7F\u52B2\u6273\u4F4F\uFF1B\u7FFB\u4E66\u9875\u3001\u63FF\u7535\u94C3\u4E5F\u5C11\u4E0D\u4E86\u5B83\u3002\u53EF\u8BA8\u5DE7\u7684\u4E8B\u2014\u2014\u6BD4\u5982\u62DB\u547C\u4EBA\u3001\u53D7\u4EBA\u611F\u8C22\u2014\u2014\u5374\u8F6E\u4E0D\u4E0A\u5B83\u3002\u5E38\u8DDF\u5927\u62C7\u6307\u5408\u4F5C\u7684\u662F\u98DF\u6307\uFF1A\u4ED6\u59FF\u6001\u76F4\u76F4\u843D\u843D\uFF0C\u5DE5\u4F5C\u66F4\u590D\u6742\uFF0C\u62FF\u7B14\u9760\u5B83\u63A8\u7B14\u6746\uFF0C\u5371\u9669\u7684\u4E8B\u8981\u5B83\u53BB\u8BD5\u63A2\uFF0C\u5200\u4F24\u70EB\u4F24\u5B83\u6328\u5F97\u6700\u591A\uFF0C\u6253\u7535\u8BDD\u3001\u6273\u67AA\u673A\u3001\u6253\u7B97\u76D8\u90FD\u8981\u5B83\u4E3B\u6301\u3002\u5B83\u6709\u5927\u62C7\u6307\u6CA1\u6709\u7684\u673A\u654F\u3002",
        example: "\u6D41\u8840\u4E86\u8981\u5B83\u6309\u4F4F\uFF0C\u55B7\u6C34\u4E86\u8981\u5B83\u62B5\u4F4F\u2014\u2014\u5927\u62C7\u6307\u603B\u5728\u5E72\u6700\u5403\u529B\u7684\u6D3B\u3002",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F44D}", "\u{1F446}", "\u{1F4AA}"], title: "\u80AF\u5403\u82E6\u7684\u62C7\u6307\u4E0E\u673A\u654F\u7684\u98DF\u6307", text: "\u5927\u62C7\u6307\u6700\u80AF\u5403\u82E6\uFF0C\u98DF\u6307\u6700\u673A\u654F\u80FD\u5E72\u3002" },
        check: { q: "\u4E94\u6307\u4E2D\u6700\u80AF\u5403\u82E6\u7684\u662F\u54EA\u6839\uFF1F", options: ["\u5927\u62C7\u6307", "\u4E2D\u6307", "\u5C0F\u6307"], answer: 0 }
      },
      {
        title: "\u56E2\u7ED3\u4E00\u81F4\u624D\u6709\u529B\u91CF",
        text: "\u4E2D\u6307\u5C45\u4E2D\u592E\uFF0C\u4E2A\u5B50\u6700\u9AD8\uFF0C\u5DE6\u53F3\u90FD\u6709\u5C4F\u969C\uFF0C\u4ECE\u4E0D\u76F4\u63A5\u78B0\u4E1C\u897F\uFF0C\u517B\u5C0A\u5904\u4F18\uFF0C\u505A\u4E8B\u540D\u4E49\u4E0A\u53C2\u52A0\u3001\u5B9E\u9645\u5E76\u4E0D\u51FA\u529B\u3002\u65E0\u540D\u6307\u548C\u5C0F\u6307\u4F53\u6001\u79C0\u4E3D\u3001\u6837\u5B50\u53EF\u7231\uFF0C\u4F46\u80FD\u529B\u8584\u5F31\uFF0C\u7528\u5904\u662F\u7814\u8102\u7C89\u3001\u8638\u836F\u672B\u3001\u638F\u8033\u6735\uFF1B\u4E0D\u8FC7\u5728\u4E1D\u7AF9\u7BA1\u5F26\u4E0A\uFF0C\u5B83\u4EEC\u7684\u672C\u9886\u53EF\u4E0D\u8F93\u7ED9\u522B\u4EBA\u2014\u2014\u821E\u8E48\u6F14\u5458\u7684\u624B\u6307\u4F5C\u201C\u5170\u82B1\u201D\u72B6\uFF0C\u6700\u4F18\u96C5\u7684\u5C31\u662F\u8FD9\u4E24\u6839\u3002\u8BFE\u6587\u6700\u540E\u70B9\u660E\u4E2D\u5FC3\uFF1A\u624B\u6307\u7684\u5168\u4F53\uFF0C\u540C\u4EBA\u7FA4\u7684\u5168\u4F53\u4E00\u6837\uFF0C\u4E94\u6839\u624B\u6307\u5982\u679C\u56E2\u7ED3\u4E00\u81F4\uFF0C\u6210\u4E3A\u4E00\u4E2A\u62F3\u5934\uFF0C\u90A3\u5C31\u6839\u6839\u6709\u7528\u3001\u6839\u6839\u6709\u529B\u91CF\uFF0C\u4E0D\u518D\u6709\u4EC0\u4E48\u5F3A\u5F31\u3001\u7F8E\u4E11\u4E4B\u5206\u4E86\u3002",
        example: "\u4E94\u6839\u624B\u6307\u64E6\u6210\u62F3\u5934\uFF0C\u529B\u91CF\u5927\u5F97\u53EF\u4EE5\u51FB\u788E\u4E1C\u897F\u2014\u2014\u56E2\u7ED3\u5C31\u662F\u529B\u91CF\u3002",
        figure: { type: "scene", bg: "indoor", emojis: ["\u270A", "\u{1F91D}", "\u{1F31F}"], title: "\u63E1\u6210\u62F3\u5934\u7684\u4E94\u6307", text: "\u4E94\u6307\u6525\u6210\u62F3\u5934\uFF0C\u6839\u6839\u6709\u7528\u3001\u6839\u6839\u6709\u529B\u91CF\u3002" },
        check: { q: "\u8BFE\u6587\u501F\u4E94\u6839\u624B\u6307\u544A\u8BC9\u4EBA\u4EEC\u4EC0\u4E48\u9053\u7406\uFF1F", options: ["\u56E2\u7ED3\u4E00\u81F4\uFF0C\u6839\u6839\u6709\u7528\uFF0C\u6839\u6839\u6709\u529B\u91CF", "\u4E2D\u6307\u6700\u5C0A\u8D35", "\u597D\u770B\u7684\u624B\u6307\u6700\u6709\u7528"], answer: 0 }
      }
    ],
    rhyme: "\u5341\u6839\u624B\u6307\u4E0D\u79BB\u8EAB\uFF0C\u4E94\u6839\u6027\u683C\u5404\u4E0D\u540C\uFF1B\n\u62C7\u6307\u80AF\u5403\u82E6\uFF0C\u98DF\u6307\u6700\u673A\u654F\uFF1B\n\u4E2D\u6307\u517B\u5C0A\u53C8\u5904\u4F18\uFF0C\u65E0\u540D\u5C0F\u6307\u672C\u9886\u8584\uFF1B\n\u4E94\u6307\u56E2\u7ED3\u6210\u62F3\u5934\uFF0C\u6839\u6839\u6709\u7528\u6709\u529B\u91CF\u3002",
    points: [
      "\u8BFE\u6587\u7528\u62DF\u4EBA\u624B\u6CD5\uFF0C\u628A\u4E94\u6839\u624B\u6307\u5199\u6210\u4E94\u79CD\u4E0D\u540C\u6027\u683C\u7684\u4EBA\uFF1A\u5927\u62C7\u6307\u80AF\u5403\u82E6\uFF0C\u98DF\u6307\u673A\u654F\u80FD\u5E72\u3002",
      "\u4E2D\u6307\u5C45\u4E8E\u4E2D\u592E\u3001\u517B\u5C0A\u5904\u4F18\uFF0C\u505A\u4E8B\u4E0D\u51FA\u529B\uFF1B\u65E0\u540D\u6307\u3001\u5C0F\u6307\u4F53\u6001\u79C0\u4E3D\u4F46\u80FD\u529B\u8584\u5F31\uFF0C\u5728\u4E1D\u7AF9\u7BA1\u5F26\u4E0A\u5F88\u6709\u7528\u3002",
      "\u4E2D\u5FC3\u53E5\uFF1A\u624B\u6307\u7684\u5168\u4F53\u540C\u4EBA\u7FA4\u7684\u5168\u4F53\u4E00\u6837\uFF0C\u56E2\u7ED3\u4E00\u81F4\u6210\u4E3A\u62F3\u5934\uFF0C\u5C31\u6839\u6839\u6709\u7528\u3001\u6839\u6839\u6709\u529B\u91CF\u3002",
      "\u5199\u4F5C\u7279\u70B9\uFF1A\u8BED\u8A00\u5E7D\u9ED8\u98CE\u8DA3\uFF0C\u501F\u624B\u6307\u8BB2\u201C\u56E2\u7ED3\u624D\u6709\u529B\u91CF\u201D\u7684\u9053\u7406\u3002"
    ],
    quiz: { q: "\u300A\u624B\u6307\u300B\u4E00\u6587\u60F3\u544A\u8BC9\u6211\u4EEC\u4EC0\u4E48\uFF1F", options: ["\u56E2\u7ED3\u4E00\u81F4\u624D\u6700\u6709\u529B\u91CF", "\u4E2D\u6307\u957F\u5F97\u6700\u6F02\u4EAE", "\u6BCF\u6839\u624B\u6307\u90FD\u8981\u5355\u72EC\u7EC3"], answer: 0 }
  },
  "chinese-g5-b-8-3": {
    example: "\u8D39\u5965\u591A\u7F57\u592B\u5728\u4E5D\u5C81\u65F6\uFF0C\u5C31\u201C\u53D1\u73B0\u201D\u4E86\u80DA\u80CE\u53D1\u80B2\u7684\u89C4\u5F8B\uFF0C\u800C\u4E14\u8FD9\u5B8C\u5168\u662F\u4ED6\u72EC\u7ACB\u601D\u8003\u7684\u7ED3\u679C\uFF01\u53EF\u8FD9\u4E2A\u53D1\u73B0\u540E\u6765\u7ADF\u8BA9\u4ED6\u5F53\u4F17\u53D7\u5230\u60E9\u7F5A\u3002\u7AE5\u5E74\u7684\u53D1\u73B0\u85CF\u7740\u600E\u6837\u7684\u6545\u4E8B\uFF1F\u6211\u4EEC\u4E00\u8D77\u53BB\u8BFB\u300A\u7AE5\u5E74\u7684\u53D1\u73B0\u300B\u3002",
    steps: [
      {
        title: "\u68A6\u4E2D\u7684\u98DE\u884C",
        text: "\u201C\u6211\u201D\u7684\u53D1\u73B0\u8D77\u59CB\u4E8E\u68A6\u4E2D\u98DE\u884C\u3002\u6BCF\u5929\u591C\u91CC\u201C\u6211\u201D\u90FD\u68A6\u89C1\u81EA\u5DF1\u98DE\uFF1A\u53EA\u8981\u53CC\u811A\u4E00\u70B9\uFF0C\u8F7B\u8F7B\u8DC3\u8D77\uFF0C\u5C31\u80FD\u79BB\u5F00\u5730\u9762\u98DE\u5411\u7A7A\u4E2D\u3002\u540E\u6765\u201C\u6211\u201D\u751A\u81F3\u5B66\u4F1A\u4E86\u6ED1\u7FD4\uFF0C\u5728\u8857\u9053\u4E0A\u7A7A\u3001\u767D\u6866\u6797\u68A2\u5934\u3001\u9752\u9752\u7684\u8349\u5730\u548C\u6F84\u6F88\u7684\u6E56\u9762\u4E0A\u76D8\u65CB\u3002\u8EAB\u4F53\u90A3\u6837\u8F7B\u76C8\uFF0C\u53EF\u4EE5\u968F\u5FC3\u6240\u6B32\u3001\u8FD0\u8F6C\u81EA\u5982\uFF0C\u4F3C\u4E4E\u60F3\u53BB\u54EA\u91CC\u5C31\u80FD\u98DE\u5230\u54EA\u91CC\u3002\u201C\u6211\u201D\u4EE5\u4E3A\u5168\u73ED\u53EA\u6709\u81EA\u5DF1\u6709\u98DE\u884C\u7684\u5929\u8D4B\u3002",
        example: "\u68A6\u91CC\u7684\u201C\u6211\u201D\u5F20\u5F00\u53CC\u81C2\uFF0C\u8F7B\u8F7B\u4E00\u8DC3\uFF0C\u5C31\u98DE\u4E0A\u4E86\u767D\u6866\u6797\u7684\u68A2\u5934\u3002",
        figure: { type: "scene", bg: "night", emojis: ["\u{1F319}", "\u{1F54A}\uFE0F", "\u{1F9D2}"], title: "\u5728\u68A6\u91CC\u98DE\u7FD4", text: "\u591C\u591C\u68A6\u89C1\u81EA\u5DF1\u98DE\u8FC7\u767D\u6866\u6797\u68A2\u5934\u548C\u6E56\u9762\u3002" },
        check: { q: "\u201C\u6211\u201D\u7684\u53D1\u73B0\u662F\u4ECE\u4EC0\u4E48\u5730\u65B9\u5F00\u59CB\u7684\uFF1F", options: ["\u591C\u91CC\u68A6\u89C1\u81EA\u5DF1\u4F1A\u98DE", "\u8001\u5E08\u4E0A\u8BFE\u6559\u7684", "\u770B\u4E66\u770B\u6765\u7684"], answer: 0 }
      },
      {
        title: "\u8D39\u5C3D\u5FC3\u673A\u7684\u601D\u8003",
        text: "\u6709\u4E00\u5929\u201C\u6211\u201D\u5F04\u660E\u767D\u4E86\uFF1A\u6BCF\u5230\u591C\u665A\uFF0C\u5C0F\u4F19\u4F34\u4EEC\u4E5F\u90FD\u4F1A\u5728\u68A6\u4E2D\u98DE\u817E\u3002\u7B2C\u4E8C\u5929\u5927\u5BB6\u5174\u81F4\u52C3\u52C3\u5730\u4EA4\u6D41\u6628\u591C\u7684\u68A6\uFF0C\u8FD8\u4E89\u8BBA\u53EA\u9760\u505A\u68A6\u80FD\u4E0D\u80FD\u98DE\u4E0A\u5929\u3002\u201C\u6211\u201D\u4FBF\u8D39\u5C3D\u5FC3\u673A\u601D\u8003\uFF1A\u4EBA\u662F\u7531\u7EC6\u80DE\u6784\u6210\u7684\u2026\u2026\u7EC6\u80DE\u662F\u8BB8\u591A\u7684\u2026\u2026\u201C\u6211\u201D\u7EC8\u4E8E\u5F97\u51FA\u7ED3\u8BBA\uFF1A\u4EBA\u662F\u7531\u7EC6\u80DE\u53D8\u5316\u800C\u6765\u7684\uFF0C\u800C\u7EC6\u80DE\u662F\u4ECE\u6BCD\u4EB2\u7684\u809A\u5B50\u91CC\u53D1\u80B2\u51FA\u6765\u7684\u3002\u8FD9\u4F7F\u201C\u6211\u201D\u975E\u5E38\u5174\u594B\u2014\u2014\u4E5D\u5C81\u7684\u201C\u6211\u201D\uFF0C\u7ADF\u72EC\u81EA\u201C\u53D1\u73B0\u201D\u4E86\u80DA\u80CE\u53D1\u80B2\u7684\u89C4\u5F8B\u3002",
        example: "\u201C\u4EBA\u662F\u7531\u7EC6\u80DE\u6784\u6210\u7684\uFF0C\u7EC6\u80DE\u662F\u4ECE\u5988\u5988\u809A\u5B50\u91CC\u53D1\u80B2\u51FA\u6765\u7684\u2026\u2026\u201D\u4E00\u4E2A\u5927\u80C6\u7684\u7ED3\u8BBA\u8BDE\u751F\u4E86\u3002",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F52C}", "\u{1F914}", "\u{1F4A1}"], title: "\u601D\u8003\u7EC6\u80DE\u7684\u79D8\u5BC6", text: "\u8D39\u5FC3\u601D\u8003\uFF1A\u4EBA\u7531\u7EC6\u80DE\u53D8\u5316\u800C\u6765\uFF0C\u591A\u4E48\u60CA\u4EBA\u3002" },
        check: { q: "\u201C\u6211\u201D\u72EC\u7ACB\u601D\u8003\u5F97\u51FA\u7684\u7ED3\u8BBA\u662F\u4EC0\u4E48\uFF1F", options: ["\u4EBA\u7531\u7EC6\u80DE\u53D8\u5316\u800C\u6765\uFF0C\u7EC6\u80DE\u4ECE\u6BCD\u4EB2\u809A\u5B50\u91CC\u53D1\u80B2\u51FA\u6765", "\u4EBA\u4F1A\u98DE\u662F\u56E0\u4E3A\u6709\u7FC5\u8180", "\u7EC6\u80DE\u662F\u4ECE\u5929\u4E0A\u6389\u4E0B\u6765\u7684"], answer: 0 }
      },
      {
        title: "\u7B11\u51FA\u58F0\u7684\u4EE3\u4EF7\u4E0E\u5B89\u6170",
        text: "\u4E8B\u60C5\u8FC7\u53BB\u4E86\u4E09\u5E74\uFF0C\u6709\u4E00\u6B21\u201C\u6211\u201D\u60F3\u8D77\u81EA\u5DF1\u7684\u53D1\u73B0\uFF0C\u60C5\u4E0D\u81EA\u7981\u7B11\u51FA\u4E86\u58F0\uFF0C\u7ADF\u5728\u8BFE\u5802\u4E0A\u5F53\u4F17\u53D7\u5230\u60E9\u7F5A\u2014\u2014\u88AB\u8001\u5E08\u7F5A\u7AD9\uFF0C\u8FD8\u88AB\u8D76\u51FA\u4E86\u6559\u5BA4\u3002\u53EF\u662F\u7AD9\u5728\u5916\u9762\uFF0C\u201C\u6211\u201D\u53CD\u800C\u60F3\u51FA\u4E00\u6761\u81EA\u6211\u5B89\u6170\u7684\u7406\u7531\uFF1A\u201C\u6211\u201D\u660E\u767D\u4E86\u2014\u2014\u4E16\u754C\u4E0A\u91CD\u5927\u7684\u53D1\u660E\u4E0E\u53D1\u73B0\uFF0C\u6709\u65F6\u8FD8\u9762\u4E34\u7740\u53D7\u5230\u9A71\u9010\u548C\u8FEB\u5BB3\u7684\u98CE\u9669\u3002\u5929\u771F\u7684\u5B69\u5B50\u7528\u8FD9\u53E5\u8BDD\u5B89\u6170\u81EA\u5DF1\uFF0C\u65E2\u8BA9\u4EBA\u53D1\u7B11\uFF0C\u53C8\u8BA9\u4EBA\u4F69\u670D\u4ED6\u575A\u6301\u72EC\u7ACB\u601D\u8003\u3001\u6562\u4E8E\u60F3\u8C61\u7684\u52B2\u513F\u3002",
        example: "\u88AB\u8D76\u51FA\u6559\u5BA4\u7684\u201C\u6211\u201D\u53CD\u800C\u7B11\u4E86\uFF1A\u5927\u53D1\u660E\u5BB6\u4E0D\u4E5F\u5E38\u5E38\u53D7\u59D4\u5C48\u5417\uFF1F",
        figure: { type: "scene", bg: "indoor", emojis: ["\u{1F6AA}", "\u{1F604}", "\u{1F9E0}"], title: "\u6559\u5BA4\u5916\u7684\u201C\u5B89\u6170\u201D", text: "\u60F3\u8D77\u53D1\u73B0\u7B11\u51FA\u58F0\u88AB\u7F5A\uFF0C\u6559\u5BA4\u5916\u81EA\u6211\u5B89\u6170\u3002" },
        check: { q: "\u201C\u6211\u201D\u88AB\u7F5A\u540E\u60F3\u51FA\u4E86\u4EC0\u4E48\u81EA\u6211\u5B89\u6170\u7684\u7406\u7531\uFF1F", options: ["\u91CD\u5927\u7684\u53D1\u660E\u4E0E\u53D1\u73B0\u6709\u65F6\u4F1A\u9762\u4E34\u9A71\u9010\u548C\u8FEB\u5BB3", "\u4E0B\u6B21\u4E0A\u8BFE\u4E0D\u7B11\u4E86", "\u518D\u4E5F\u4E0D\u601D\u8003\u95EE\u9898\u4E86"], answer: 0 }
      }
    ],
    rhyme: "\u4E5D\u5C81\u201C\u53D1\u73B0\u201D\u80DA\u80CE\u5F8B\uFF0C\u72EC\u7ACB\u601D\u8003\u5F97\u7ED3\u8BBA\uFF1B\n\u591C\u591C\u68A6\u4E2D\u98DE\u4E0A\u5929\uFF0C\u8FFD\u6839\u95EE\u5E95\u4E0D\u80AF\u6B47\uFF1B\n\u8BFE\u5802\u4E00\u7B11\u88AB\u7F5A\u7AD9\uFF0C\u53D1\u660E\u53D1\u73B0\u6709\u4EE3\u4EF7\uFF1B\n\u5929\u771F\u597D\u5947\u53C8\u575A\u6301\uFF0C\u7AE5\u5E74\u53D1\u73B0\u771F\u6709\u8DA3\u3002",
    points: [
      "\u201C\u6211\u201D\u7684\u53D1\u73B0\u5B8C\u5168\u662F\u72EC\u7ACB\u601D\u8003\u7684\u7ED3\u679C\uFF1A\u4ECE\u68A6\u4E2D\u98DE\u884C\uFF0C\u5230\u601D\u8003\u7EC6\u80DE\uFF0C\u6700\u540E\u5F97\u51FA\u80DA\u80CE\u53D1\u80B2\u7684\u89C4\u5F8B\u3002",
      "\u201C\u6211\u201D\u5728\u8BFE\u5802\u4E0A\u60F3\u8D77\u81EA\u5DF1\u7684\u53D1\u73B0\u7B11\u51FA\u4E86\u58F0\uFF0C\u88AB\u7F5A\u7AD9\u5E76\u88AB\u8D76\u51FA\u6559\u5BA4\u3002",
      "\u81EA\u6211\u5B89\u6170\uFF1A\u201C\u6211\u201D\u660E\u767D\u4E86\u4E16\u754C\u4E0A\u91CD\u5927\u7684\u53D1\u660E\u4E0E\u53D1\u73B0\uFF0C\u6709\u65F6\u8FD8\u9762\u4E34\u7740\u53D7\u5230\u9A71\u9010\u548C\u8FEB\u5BB3\u7684\u98CE\u9669\u3002",
      "\u8BFE\u6587\u8BED\u8A00\u5E7D\u9ED8\uFF0C\u5199\u51FA\u513F\u7AE5\u7684\u5929\u771F\u597D\u5947\u4E0E\u6562\u4E8E\u60F3\u8C61\u3001\u575A\u6301\u63A2\u7A76\u7684\u7CBE\u795E\u3002"
    ],
    quiz: { q: "\u4F5C\u8005\u56DE\u5FC6\u7AE5\u5E74\u7684\u53D1\u73B0\uFF0C\u6700\u60F3\u8BA9\u6211\u4EEC\u611F\u53D7\u5230\u4EC0\u4E48\uFF1F", options: ["\u513F\u7AE5\u5929\u771F\u597D\u5947\u3001\u6562\u4E8E\u60F3\u8C61\u3001\u72EC\u7ACB\u601D\u8003\u7684\u53EF\u8D35", "\u4E0A\u8BFE\u4E0D\u80FD\u7B11", "\u505A\u68A6\u4F1A\u8BA9\u4EBA\u53D8\u7B28"], answer: 0 }
  }
};

