        check: { q: "\u5728\u963F\u5ED6\u6C99\u82E6\u96BE\u7684\u7AE5\u5E74\u91CC\uFF0C\u8C01\u7ED9\u4E86\u4ED6\u6E29\u6696\u548C\u5149\u4EAE\uFF1F", options: ["\u5916\u7956\u6BCD", "\u5916\u7956\u7236", "\u4E24\u4E2A\u8205\u8205"], answer: 0 }
